window.AOG_STANDARDS = {"built":"2026-09-25","courses":[{"key":"sci","name":"Science","subject":"K–12 · 27 units","hub":"/science-course","hubExists":true,"framework":{"name":"Next Generation Science Standards (Illinois Learning Standards for Science)","short":"NGSS","note":"Codes are NGSS performance expectations (grade or band, discipline, number) as adopted in the Illinois Learning Standards for Science; alignment is the course author's judgment, not a certification."},"units":[{"n":1,"title":"Pushes, Pulls and Stuff","band":"Grades K–2","strand":"Physical Science","link":"/sci1","standards":[{"code":"K-PS2-1","text":"Investigate how different strengths and directions of pushes and pulls change an object's motion."},{"code":"K-PS2-2","text":"Analyze a design that uses a push or pull to change an object's speed or direction."},{"code":"2-PS1-1","text":"Describe and classify materials by observable properties such as color, texture and hardness."},{"code":"2-PS1-2","text":"Test materials to decide which properties suit them for a given purpose."},{"code":"2-PS1-3","text":"Show that a large object can be built from small pieces and taken apart into new things."},{"code":"2-PS1-4","text":"Argue from evidence that some heating and cooling changes reverse and some do not."}]},{"n":2,"title":"Light, Sound and Waves","band":"Grades K–2","strand":"Physical Science","link":"/sci2","standards":[{"code":"1-PS4-1","text":"Investigate to show that vibrating materials make sound and sound can make materials vibrate."},{"code":"1-PS4-2","text":"Use observations to explain that objects are seen only when lit."},{"code":"1-PS4-3","text":"Test how light passes through, partly through, or is blocked by different materials."},{"code":"1-PS4-4","text":"Design and build a device that uses light or sound to send a message over a distance."}]},{"n":3,"title":"Living Things and Where They Live","band":"Grades K–2","strand":"Life Science","link":"/sci3","standards":[{"code":"K-LS1-1","text":"Use observations to describe what plants and animals need to survive."},{"code":"K-ESS2-2","text":"Argue that plants and animals can change their environment to meet their needs."},{"code":"1-LS1-1","text":"Design a solution that mimics how plant or animal parts help them survive and grow."},{"code":"1-LS3-1","text":"Use evidence to show young plants and animals resemble but are not identical to their parents."},{"code":"2-LS4-1","text":"Observe plants and animals to compare the diversity of life in different habitats."},{"code":"2-LS2-2","text":"Build a model of how animals help disperse seeds or pollinate plants."}]},{"n":4,"title":"Earth, Sky and Weather","band":"Grades K–2","strand":"Earth and Space Science","link":"/sci4","standards":[{"code":"K-ESS2-1","text":"Record local weather over time to describe patterns."},{"code":"K-PS3-1","text":"Observe the warming effect of sunlight on Earth's surface."},{"code":"1-ESS1-1","text":"Observe and predict patterns in the sun, moon and stars."},{"code":"2-ESS1-1","text":"Use evidence that Earth events can happen quickly or slowly."},{"code":"2-ESS2-1","text":"Compare designs that slow wind or water from changing the shape of the land."},{"code":"2-ESS2-3","text":"Get information that water on Earth is found as liquid and as solid ice."}]},{"n":5,"title":"Forces, Motion and Energy","band":"Grades 3–5","strand":"Physical Science","link":"/sci5","standards":[{"code":"3-PS2-1","text":"Investigate the effects of balanced and unbalanced forces on an object's motion."},{"code":"3-PS2-2","text":"Observe patterns in motion that can predict future motion."},{"code":"3-PS2-3","text":"Ask questions about cause and effect in electric or magnetic interactions between objects."},{"code":"4-PS3-1","text":"Explain, with evidence, the relationship between an object's speed and its energy."},{"code":"4-PS3-2","text":"Show that energy moves from place to place by sound, light, heat and electric currents."},{"code":"4-PS3-4","text":"Design, test and refine a device that converts energy from one form to another."}]},{"n":6,"title":"Matter and Waves","band":"Grades 3–5","strand":"Physical Science","link":"/sci6","standards":[{"code":"5-PS1-1","text":"Develop a model showing matter is made of particles too small to see."},{"code":"5-PS1-2","text":"Measure and graph to show total weight is conserved through heating, cooling or mixing."},{"code":"5-PS1-4","text":"Investigate whether mixing two substances produces a new substance."},{"code":"4-PS4-1","text":"Model waves in terms of amplitude and wavelength and how they move objects."},{"code":"4-PS4-2","text":"Model how light reflecting from objects into the eye allows objects to be seen."},{"code":"4-PS4-3","text":"Design and compare solutions that use patterns to transfer information."}]},{"n":7,"title":"Life: Cycles, Traits and Survival","band":"Grades 3–5","strand":"Life Science","link":"/sci7","standards":[{"code":"3-LS1-1","text":"Model life cycles of organisms with their shared stages of birth, growth, reproduction and death."},{"code":"3-LS3-1","text":"Analyze data showing that inherited traits vary within groups of similar organisms."},{"code":"3-LS3-2","text":"Use evidence that the environment can influence an organism's traits."},{"code":"3-LS4-2","text":"Explain how variations in traits can give individuals advantages in survival and reproduction."},{"code":"4-LS1-1","text":"Argue that plants and animals have internal and external structures that support survival and reproduction."},{"code":"4-LS1-2","text":"Model how animals receive sensory information, process it in the brain and respond."}]},{"n":8,"title":"Ecosystems and the Flow of Energy","band":"Grades 3–5","strand":"Life Science","link":"/sci8","standards":[{"code":"5-PS3-1","text":"Model how energy in animals' food originally came from the sun."},{"code":"5-LS1-1","text":"Argue from evidence that plants get growth materials chiefly from air and water."},{"code":"5-LS2-1","text":"Model the movement of matter among plants, animals, decomposers and the environment."},{"code":"3-LS4-4","text":"Argue for a solution to a problem caused when environmental change affects the organisms living there."}]},{"n":9,"title":"Earth, Weather and Space","band":"Grades 3–5","strand":"Earth and Space Science","link":"/sci9","standards":[{"code":"3-ESS2-2","text":"Obtain and combine information about climates in different regions of the world."},{"code":"4-ESS1-1","text":"Use evidence from rock layers and fossils to explain changes in a landscape over time."},{"code":"4-ESS2-1","text":"Investigate the effects of weathering and rate of erosion by water, ice, wind or plants."},{"code":"5-ESS1-2","text":"Represent data to reveal patterns of daily and seasonal changes caused by Earth's motion."},{"code":"5-ESS2-1","text":"Model how the geosphere, biosphere, hydrosphere and atmosphere interact."},{"code":"5-ESS3-1","text":"Gather information about how communities use science to protect Earth's resources and environments."}]},{"n":10,"title":"Matter and Its Interactions","band":"Grades 6–8","strand":"Physical Science","link":"/sci10","standards":[{"code":"MS-PS1-1","text":"Develop models of the atomic composition of simple molecules and extended structures."},{"code":"MS-PS1-2","text":"Analyze property data before and after substances interact to detect a chemical reaction."},{"code":"MS-PS1-4","text":"Model how particle motion and state change when thermal energy is added or removed."},{"code":"MS-PS1-5","text":"Model how atoms rearrange in a reaction while total mass is conserved."},{"code":"MS-PS1-6","text":"Design and test a device that releases or absorbs thermal energy by chemical processes."}]},{"n":11,"title":"Forces, Motion and Energy","band":"Grades 6–8","strand":"Physical Science","link":"/sci11","standards":[{"code":"MS-PS2-1","text":"Apply Newton's third law to design a solution to a collision problem."},{"code":"MS-PS2-2","text":"Investigate how the sum of forces and the object's mass determine its change in motion."},{"code":"MS-PS2-4","text":"Argue from evidence that gravitational interactions depend on the masses of the objects."},{"code":"MS-PS3-1","text":"Interpret graphical data relating kinetic energy to mass and speed."},{"code":"MS-PS3-3","text":"Design, build and test a device that minimizes or maximizes thermal energy transfer."},{"code":"MS-PS3-5","text":"Argue from evidence that when kinetic energy changes, energy is transferred to or from the object."}]},{"n":12,"title":"Waves and Information","band":"Grades 6–8","strand":"Physical Science","link":"/sci12","standards":[{"code":"MS-PS4-1","text":"Use models to describe how a wave's amplitude relates to its energy."},{"code":"MS-PS4-2","text":"Model how waves are reflected, absorbed or transmitted by various materials."},{"code":"MS-PS4-3","text":"Evaluate evidence that digital signals are more reliable than analog for transmitting information."}]},{"n":13,"title":"Cells, Bodies and Reproduction","band":"Grades 6–8","strand":"Life Science","link":"/sci13","standards":[{"code":"MS-LS1-1","text":"Investigate to show that living things are made of cells, either one or many."},{"code":"MS-LS1-2","text":"Model a cell and explain how its parts contribute to its function."},{"code":"MS-LS1-3","text":"Argue from evidence that a body is a system of interacting subsystems of cells, tissues and organs."},{"code":"MS-LS1-4","text":"Argue how animal behaviors and plant structures increase reproductive success."},{"code":"MS-LS1-6","text":"Explain with evidence how photosynthesis cycles matter and moves energy into organisms."},{"code":"MS-LS1-8","text":"Gather information on how sensory receptors send messages to the brain for memory or response."}]},{"n":14,"title":"Ecosystems, Heredity and Evolution","band":"Grades 6–8","strand":"Life Science","link":"/sci14","standards":[{"code":"MS-LS2-1","text":"Analyze data on how resource availability affects organisms and populations in an ecosystem."},{"code":"MS-LS2-5","text":"Evaluate competing design solutions for maintaining biodiversity and ecosystem services."},{"code":"MS-LS3-1","text":"Model why structural changes to genes may affect proteins and an organism's traits."},{"code":"MS-LS3-2","text":"Model why asexual reproduction yields identical genes while sexual reproduction yields variation."},{"code":"MS-LS4-1","text":"Analyze fossil record patterns documenting existence, diversity and change of life forms."},{"code":"MS-LS4-4","text":"Explain how genetic variations of traits affect survival and reproduction in an environment."}]},{"n":15,"title":"Earth and Space Systems","band":"Grades 6–8","strand":"Earth and Space Science","link":"/sci15","standards":[{"code":"MS-ESS1-1","text":"Model the Earth-sun-moon system to explain lunar phases, eclipses and seasons."},{"code":"MS-ESS1-4","text":"Use rock strata evidence to organize Earth's 4.6-billion-year history."},{"code":"MS-ESS2-2","text":"Explain how geoscience processes change Earth's surface at varying scales."},{"code":"MS-ESS2-4","text":"Model the cycling of water through Earth's systems driven by sunlight and gravity."},{"code":"MS-ESS3-3","text":"Design a method for monitoring and minimizing human impact on the environment."},{"code":"MS-ESS3-5","text":"Ask questions to clarify evidence of factors causing the rise in global temperatures."}]},{"n":16,"title":"Biology: Cells and Energy","band":"Grades 9–10","strand":"Life Science","link":"/sci16","standards":[{"code":"HS-LS1-1","text":"Explain how DNA structure determines proteins that carry out essential functions."},{"code":"HS-LS1-2","text":"Model how interacting systems in multicellular organisms provide specific functions."},{"code":"HS-LS1-3","text":"Investigate to show feedback mechanisms maintain homeostasis."},{"code":"HS-LS1-4","text":"Model how mitosis and differentiation produce and maintain complex organisms."},{"code":"HS-LS1-5","text":"Model how photosynthesis transforms light energy into stored chemical energy."},{"code":"HS-LS1-7","text":"Model how cellular respiration breaks bonds in food and releases energy."}]},{"n":17,"title":"Biology: Genetics and Evolution","band":"Grades 9–10","strand":"Life Science","link":"/sci17","standards":[{"code":"HS-LS3-1","text":"Ask questions about how DNA and chromosomes pass traits from parents to offspring."},{"code":"HS-LS3-2","text":"Explain how inheritable variation arises from meiosis, mutation and errors in replication."},{"code":"HS-LS4-1","text":"Communicate evidence for common ancestry and biological evolution."},{"code":"HS-LS4-2","text":"Explain how the process of evolution results mainly from four key factors."},{"code":"HS-LS4-4","text":"Use evidence to explain how natural selection leads to adaptation of populations."},{"code":"HS-LS4-5","text":"Evaluate evidence that environmental change may lead to new species or extinction."}]},{"n":18,"title":"Biology: Ecosystems and Human Impact","band":"Grades 9–10","strand":"Life Science","link":"/sci18","standards":[{"code":"HS-LS2-1","text":"Use mathematical representations to explain factors affecting carrying capacity."},{"code":"HS-LS2-2","text":"Use math to support explanations about biodiversity and populations in ecosystems."},{"code":"HS-LS2-4","text":"Use math to model the cycling of matter and flow of energy among organisms in an ecosystem."},{"code":"HS-LS2-6","text":"Evaluate claims that ecosystems stay stable under modest change but can shift under larger ones."},{"code":"HS-LS2-7","text":"Design, evaluate and refine a solution reducing human impact on the environment and biodiversity."},{"code":"HS-LS2-8","text":"Evaluate evidence for how group behavior improves individuals' chances of survival and reproduction."}]},{"n":19,"title":"Physical Science: Matter and Reactions","band":"Grades 9–10","strand":"Physical Science","link":"/sci19","standards":[{"code":"HS-PS1-1","text":"Use the periodic table to predict relative element properties from outermost electron patterns."},{"code":"HS-PS1-2","text":"Construct explanations of simple chemical reactions using periodic table patterns."},{"code":"HS-PS1-4","text":"Model how bond energy changes explain whether a reaction releases or absorbs energy."},{"code":"HS-PS1-5","text":"Explain how changes in temperature or concentration affect reaction rate."},{"code":"HS-PS1-7","text":"Use math to show that atoms and mass are conserved in a chemical reaction."},{"code":"HS-PS1-8","text":"Model the changes in nucleus composition and energy released in fission, fusion and decay."}]},{"n":20,"title":"Physical Science: Forces, Energy and Waves","band":"Grades 9–10","strand":"Physical Science","link":"/sci20","standards":[{"code":"HS-PS2-1","text":"Analyze data to support Newton's second law relating net force, mass and acceleration."},{"code":"HS-PS2-2","text":"Use math to show that total momentum of a system is conserved when no net external force acts."},{"code":"HS-PS2-4","text":"Use math to describe and predict gravitational and electrostatic forces between objects."},{"code":"HS-PS3-1","text":"Use computational models to calculate energy change in a system's components."},{"code":"HS-PS3-2","text":"Model energy at the macroscopic scale as combined motion and relative-position energy of particles."},{"code":"HS-PS4-1","text":"Use math to relate wave frequency, wavelength and speed in various media."}]},{"n":21,"title":"Earth and Space","band":"Grades 9–10","strand":"Earth and Space Science","link":"/sci21","standards":[{"code":"HS-ESS1-1","text":"Model the sun's fusion-driven release of energy that reaches Earth as radiation."},{"code":"HS-ESS1-2","text":"Use astronomical evidence, such as redshift and background radiation, to support the Big Bang theory."},{"code":"HS-ESS2-1","text":"Model how Earth's internal and surface processes operate at different scales to form landforms."},{"code":"HS-ESS2-4","text":"Use a model to describe how energy flow variations cause changes in climate."},{"code":"HS-ESS2-6","text":"Model how carbon cycles among the hydrosphere, atmosphere, geosphere and biosphere."},{"code":"HS-ESS3-4","text":"Evaluate or refine a technological solution that reduces human impact on natural systems."}]},{"n":22,"title":"Chemistry: Atoms, Bonding and Reactions","band":"Grades 11–12","strand":"Chemistry","link":"/sci22","standards":[{"code":"HS-PS1-1","text":"Use the periodic table to predict relative element properties from outermost electron patterns."},{"code":"HS-PS1-2","text":"Explain simple chemical reactions from periodic table patterns and outer electron states."},{"code":"HS-PS1-3","text":"Investigate how bulk properties of substances arise from the strength of electrical forces between particles."},{"code":"HS-PS1-5","text":"Explain how temperature and concentration changes affect the rate of a reaction."},{"code":"HS-PS1-6","text":"Refine a design of a chemical system to increase products at equilibrium."}]},{"n":23,"title":"Chemistry: Stoichiometry, Solutions and Energy","band":"Grades 11–12","strand":"Chemistry","link":"/sci23","standards":[{"code":"HS-PS1-7","text":"Use math to show that atoms and mass are conserved in chemical reactions."},{"code":"HS-PS1-4","text":"Model how bond energy changes explain whether a reaction releases or absorbs energy."},{"code":"HS-PS1-3","text":"Investigate how bulk properties relate to electrical forces between particles."},{"code":"HS-PS3-4","text":"Investigate to show that two objects at different temperatures reach a uniform temperature in a closed system."}]},{"n":24,"title":"Physics: Motion and Forces","band":"Grades 11–12","strand":"Physics","link":"/sci24","standards":[{"code":"HS-PS2-1","text":"Analyze data to support Newton's second law relating net force, mass and acceleration."},{"code":"HS-PS2-2","text":"Use math to show momentum is conserved in a system with no net external force."},{"code":"HS-PS2-3","text":"Design and refine a device that minimizes force on an object during a collision."},{"code":"HS-PS2-4","text":"Use math to describe and predict gravitational and electrostatic forces between objects."}]},{"n":25,"title":"Physics: Energy, Waves and Electricity","band":"Grades 11–12","strand":"Physics","link":"/sci25","standards":[{"code":"HS-PS3-1","text":"Use computational models to calculate energy changes among components of a system."},{"code":"HS-PS3-2","text":"Model energy at the macroscopic scale as combined particle motion and position energies."},{"code":"HS-PS3-3","text":"Design, build and refine a device that converts one form of energy into another."},{"code":"HS-PS2-5","text":"Investigate to show electric currents produce magnetic fields and changing magnetic fields produce currents."},{"code":"HS-PS4-1","text":"Use math to relate wave frequency, wavelength and speed in various media."},{"code":"HS-PS4-3","text":"Evaluate claims that electromagnetic radiation is best described as a wave or as particles."}]},{"n":26,"title":"Environmental Science","band":"Grades 11–12","strand":"Earth and Environmental Science","link":"/sci26","standards":[{"code":"HS-ESS3-1","text":"Explain how resource availability, natural hazards and climate change affect human activity."},{"code":"HS-ESS3-2","text":"Evaluate competing designs for developing and managing resources by cost-benefit ratios."},{"code":"HS-ESS3-3","text":"Use a computational simulation to show relationships among resources, population and biodiversity."},{"code":"HS-ESS3-4","text":"Evaluate or refine a technological solution that reduces human impact on natural systems."},{"code":"HS-ESS3-5","text":"Analyze geoscience data and climate model outputs to forecast current or future climate change."},{"code":"HS-ESS3-6","text":"Use a computational model to show how human activity and Earth's systems interact."}]},{"n":27,"title":"Capstone: Argue From Evidence","band":"Grades 11–12","strand":"Science Practices","link":"/sci27","standards":[{"code":"HS-ETS1-1","text":"Analyze a major global challenge to specify criteria and constraints for solutions."},{"code":"HS-ETS1-2","text":"Break a complex real-world problem into smaller, manageable problems."},{"code":"HS-ETS1-3","text":"Evaluate a solution against prioritized criteria and trade-offs, including social and environmental impacts."},{"code":"HS-ETS1-4","text":"Use a computer simulation to model the impact of proposed solutions to a complex problem."}]}],"codes":147},{"key":"mth","name":"Mathematics","subject":"K–12 · 27 units","hub":"/math-course","hubExists":true,"framework":{"name":"Illinois Learning Standards for Mathematics (Common Core State Standards for Mathematics)","short":"IL Math (CCSS-M)","note":"Codes are Common Core State Standards for Mathematics identifiers (e.g. 2.NBT.B.5, HSA-REI.B.4) as adopted by Illinois; the alignment is the course author's judgment and is not a certification."},"units":[{"n":1,"title":"Counting and Numbers","band":"Grades K–2","strand":"Number","link":"/mth1","standards":[{"code":"K.CC.A.1","text":"Count to 100 by ones and by tens."},{"code":"K.CC.B.4","text":"Pair each object with one number name and understand the last number said tells how many."},{"code":"K.CC.C.6","text":"Decide whether one group has more, fewer or the same number of objects as another."},{"code":"1.NBT.B.2","text":"See a two-digit number as some tens and some ones, with ten as a bundle of ten ones."},{"code":"1.NBT.B.3","text":"Compare two two-digit numbers by their tens and ones using >, = and <."},{"code":"1.NBT.C.5","text":"Mentally find ten more or ten less than a two-digit number and explain why."}]},{"n":2,"title":"Adding and Subtracting","band":"Grades K–2","strand":"Operations","link":"/mth2","standards":[{"code":"K.OA.A.1","text":"Show addition as putting together or adding to and subtraction as taking apart or taking from, with objects and drawings."},{"code":"1.OA.A.1","text":"Solve add-and-subtract word problems within 20 with the unknown in any position."},{"code":"1.OA.C.6","text":"Add and subtract within 20 using strategies such as counting on, making ten and doubles."},{"code":"1.OA.D.7","text":"Understand that the equal sign means both sides are the same amount."},{"code":"2.OA.A.1","text":"Solve one- and two-step word problems within 100 involving addition and subtraction."},{"code":"2.OA.B.2","text":"Add and subtract within 20 fluently, knowing sums of two one-digit numbers from memory."}]},{"n":3,"title":"Place Value to 1,000","band":"Grades K–2","strand":"Number","link":"/mth3","standards":[{"code":"2.NBT.A.1","text":"Understand a three-digit number as amounts of hundreds, tens and ones."},{"code":"2.NBT.A.3","text":"Read and write numbers to 1,000 in numerals, words and expanded form."},{"code":"2.NBT.A.4","text":"Compare two three-digit numbers by place value using >, = and <."},{"code":"2.NBT.B.5","text":"Add and subtract within 100 fluently using place value and properties of operations."},{"code":"2.NBT.B.7","text":"Add and subtract within 1,000 with models and drawings, regrouping when needed."},{"code":"2.OA.C.3","text":"Decide whether a group of objects is even or odd."}]},{"n":4,"title":"Measuring, Time and Money","band":"Grades K–2","strand":"Measurement","link":"/mth4","standards":[{"code":"1.MD.A.2","text":"Measure a length by laying same-size units end to end with no gaps or overlaps."},{"code":"2.MD.A.1","text":"Measure lengths choosing suitable tools such as rulers, yardsticks and meter sticks."},{"code":"2.MD.C.7","text":"Tell and write time to the nearest five minutes on analog and digital clocks, using a.m. and p.m."},{"code":"2.MD.C.8","text":"Solve word problems with dollars, quarters, dimes, nickels and pennies."},{"code":"2.MD.D.9","text":"Measure lengths and show the data on a line plot."},{"code":"2.MD.D.10","text":"Make picture graphs and bar graphs and answer questions from them."}]},{"n":5,"title":"Shapes and Equal Shares","band":"Grades K–2","strand":"Geometry","link":"/mth5","standards":[{"code":"K.G.A.2","text":"Name shapes correctly no matter their size or how they are turned."},{"code":"1.G.A.1","text":"Tell defining attributes such as sides and corners from non-defining ones like color or size."},{"code":"1.G.A.2","text":"Put together two- and three-dimensional shapes to make new shapes."},{"code":"2.G.A.1","text":"Recognize and draw shapes with a given number of sides, angles or faces."},{"code":"2.G.A.2","text":"Divide a rectangle into rows and columns of same-size squares and count them."},{"code":"2.G.A.3","text":"Partition circles and rectangles into halves, thirds and fourths and describe the equal shares."}]},{"n":6,"title":"Multiplication and Division","band":"Grades 3–5","strand":"Operations","link":"/mth6","standards":[{"code":"3.OA.A.1","text":"Interpret a product of whole numbers as a number of equal groups."},{"code":"3.OA.A.2","text":"Interpret a quotient as sharing into equal groups or finding how many groups."},{"code":"3.OA.B.5","text":"Use the commutative, associative and distributive properties to multiply and divide."},{"code":"3.OA.C.7","text":"Multiply and divide within 100 fluently, knowing single-digit products from memory."},{"code":"3.OA.D.8","text":"Solve two-step word problems with the four operations and check answers by estimating."},{"code":"4.OA.A.3","text":"Solve multi-step word problems with whole numbers, interpreting any remainder."}]},{"n":7,"title":"Place Value and Multi-Digit Arithmetic","band":"Grades 3–5","strand":"Number","link":"/mth7","standards":[{"code":"4.NBT.A.1","text":"Recognize that each place is ten times the value of the place to its right."},{"code":"4.NBT.A.2","text":"Read, write and compare multi-digit numbers in numerals, words and expanded form."},{"code":"4.NBT.A.3","text":"Round multi-digit whole numbers to any place."},{"code":"4.NBT.B.4","text":"Add and subtract multi-digit whole numbers fluently with the standard algorithm."},{"code":"4.NBT.B.5","text":"Multiply multi-digit numbers using place value, area models and partial products."},{"code":"5.NBT.B.6","text":"Divide whole numbers with up to four-digit dividends and two-digit divisors, explaining the method."}]},{"n":8,"title":"Fractions","band":"Grades 3–5","strand":"Number","link":"/mth8","standards":[{"code":"3.NF.A.2","text":"Represent fractions as points on a number line built from unit fractions."},{"code":"3.NF.A.3","text":"Explain fraction equivalence and compare fractions with the same numerator or denominator."},{"code":"4.NF.B.3","text":"Add and subtract fractions and mixed numbers with like denominators, including in word problems."},{"code":"5.NF.A.1","text":"Add and subtract fractions with unlike denominators by finding equivalent fractions."},{"code":"5.NF.B.4","text":"Multiply a fraction by a whole number or a fraction, using area models."},{"code":"5.NF.B.7","text":"Divide unit fractions by whole numbers and whole numbers by unit fractions with models and stories."}]},{"n":9,"title":"Decimals","band":"Grades 3–5","strand":"Number","link":"/mth9","standards":[{"code":"4.NF.C.6","text":"Write fractions with denominators 10 and 100 as decimals."},{"code":"4.NF.C.7","text":"Compare two decimals to hundredths and record with >, = or <."},{"code":"5.NBT.A.2","text":"Explain patterns when multiplying or dividing by powers of ten, including decimal-point shifts."},{"code":"5.NBT.A.3","text":"Read, write and compare decimals to thousandths using place value."},{"code":"5.NBT.A.4","text":"Round decimals to any place."},{"code":"5.NBT.B.7","text":"Add, subtract, multiply and divide decimals to hundredths with models and place-value reasoning."}]},{"n":10,"title":"Measurement and Data","band":"Grades 3–5","strand":"Measurement","link":"/mth10","standards":[{"code":"3.MD.B.3","text":"Draw scaled picture graphs and bar graphs and solve problems using them."},{"code":"3.MD.C.7","text":"Relate area of rectangles to multiplication and find area of composite figures."},{"code":"3.MD.D.8","text":"Solve perimeter problems, including shapes with the same area but different perimeters."},{"code":"4.MD.A.1","text":"Convert larger measurement units to smaller ones within a single system."},{"code":"4.MD.A.2","text":"Solve word problems about distance, time, liquid volume, mass and money."},{"code":"5.MD.C.5","text":"Find the volume of rectangular prisms by packing unit cubes and by formula."}]},{"n":11,"title":"Geometry and the Coordinate Plane","band":"Grades 3–5","strand":"Geometry","link":"/mth11","standards":[{"code":"4.G.A.1","text":"Draw and identify points, lines, rays, angles and parallel and perpendicular lines."},{"code":"4.MD.C.6","text":"Measure and sketch angles in degrees with a protractor."},{"code":"5.G.B.4","text":"Classify two-dimensional figures in a hierarchy based on their properties."},{"code":"5.G.A.1","text":"Use ordered pairs to locate points in the first quadrant of the coordinate plane."},{"code":"5.G.A.2","text":"Graph and interpret points in the first quadrant to solve real-world problems."},{"code":"5.OA.B.3","text":"Generate two numerical patterns, compare their terms and graph the ordered pairs."}]},{"n":12,"title":"Ratios, Rates and Proportions","band":"Grades 6–8","strand":"Ratios and Proportional Relationships","link":"/mth12","standards":[{"code":"6.RP.A.1","text":"Use ratio language to describe a relationship between two quantities."},{"code":"6.RP.A.2","text":"Understand unit rates and use rate language in context."},{"code":"6.RP.A.3","text":"Solve ratio and rate problems with tables, double number lines, percents and unit conversions."},{"code":"7.RP.A.2","text":"Recognize proportional relationships and find the constant of proportionality."},{"code":"7.RP.A.3","text":"Solve multi-step ratio and percent problems such as tax, tip, discount and percent error."},{"code":"7.G.A.1","text":"Solve problems with scale drawings, computing actual lengths and areas."}]},{"n":13,"title":"The Number System","band":"Grades 6–8","strand":"Number","link":"/mth13","standards":[{"code":"6.NS.C.6","text":"Place rational numbers, including negatives, on number lines and in the coordinate plane."},{"code":"7.NS.A.1","text":"Add and subtract rational numbers using number lines and additive inverses."},{"code":"7.NS.A.2","text":"Multiply and divide rational numbers, explaining the sign rules with properties of operations."},{"code":"8.NS.A.1","text":"Distinguish rational from irrational numbers and convert repeating decimals to fractions."},{"code":"8.EE.A.1","text":"Apply the properties of integer exponents to generate equivalent expressions."},{"code":"8.EE.A.3","text":"Use scientific notation to estimate and compare very large and very small quantities."}]},{"n":14,"title":"Expressions, Equations and Inequalities","band":"Grades 6–8","strand":"Algebra Begins","link":"/mth14","standards":[{"code":"6.EE.A.2","text":"Write, read and evaluate expressions containing variables."},{"code":"6.EE.A.3","text":"Apply properties of operations to produce equivalent expressions."},{"code":"6.EE.B.7","text":"Solve one-step equations of the form x + p = q and px = q in real-world settings."},{"code":"7.EE.A.1","text":"Add, subtract, factor and expand linear expressions with rational coefficients."},{"code":"7.EE.B.4","text":"Use two-step equations and inequalities to solve word problems and graph the solutions."},{"code":"8.EE.C.7","text":"Solve linear equations in one variable, including those with the variable on both sides."}]},{"n":15,"title":"Functions and Linear Equations","band":"Grades 6–8","strand":"Algebra","link":"/mth15","standards":[{"code":"8.EE.B.5","text":"Graph proportional relationships and interpret unit rate as slope."},{"code":"8.EE.B.6","text":"Use similar triangles to explain constant slope and derive y = mx + b."},{"code":"8.EE.C.8","text":"Analyze and solve pairs of simultaneous linear equations graphically and algebraically."},{"code":"8.F.A.1","text":"Understand a function as a rule assigning exactly one output to each input."},{"code":"8.F.A.3","text":"Interpret y = mx + b as a linear function and give examples of nonlinear functions."},{"code":"8.F.B.4","text":"Construct a linear function to model a relationship and interpret its rate of change and initial value."}]},{"n":16,"title":"Geometry","band":"Grades 6–8","strand":"Geometry","link":"/mth16","standards":[{"code":"6.G.A.1","text":"Find areas of triangles and special quadrilaterals by composing and decomposing shapes."},{"code":"7.G.B.4","text":"Know and use formulas for area and circumference of a circle."},{"code":"7.G.B.5","text":"Use supplementary, complementary, vertical and adjacent angles to find unknown angles."},{"code":"8.G.A.5","text":"Establish facts about angle sums, exterior angles and angles from parallel lines cut by a transversal."},{"code":"8.G.B.7","text":"Apply the Pythagorean theorem to find unknown side lengths in real-world and mathematical problems."},{"code":"8.G.C.9","text":"Use volume formulas for cones, cylinders and spheres to solve problems."}]},{"n":17,"title":"Statistics and Probability","band":"Grades 6–8","strand":"Statistics and Probability","link":"/mth17","standards":[{"code":"6.SP.B.5","text":"Summarize numerical data sets with measures of center, spread and overall shape."},{"code":"7.SP.A.1","text":"Understand that random samples support valid inferences about a population."},{"code":"7.SP.C.7","text":"Develop probability models and compare predicted with observed frequencies."},{"code":"7.SP.C.8","text":"Find probabilities of compound events using lists, tables, tree diagrams and simulation."},{"code":"8.SP.A.1","text":"Construct and interpret scatter plots, describing clustering, outliers and association."},{"code":"8.SP.A.3","text":"Use the equation of a linear model to interpret slope and intercept in bivariate data."}]},{"n":18,"title":"Algebra I: Linear Equations, Functions and Systems","band":"Grades 9–10","strand":"Algebra","link":"/mth18","standards":[{"code":"HSA-REI.A.1","text":"Justify each step in solving an equation and build a viable argument for the solution."},{"code":"HSA-CED.A.4","text":"Rearrange formulas to highlight a quantity of interest, as in solving literal equations."},{"code":"HSF-IF.A.2","text":"Use function notation, evaluate functions and interpret statements in context."},{"code":"HSF-IF.B.4","text":"Interpret key features of graphs and tables of a function modeling a relationship."},{"code":"HSA-REI.C.6","text":"Solve systems of linear equations exactly and approximately, including by elimination."},{"code":"HSA-REI.D.12","text":"Graph solutions to linear inequalities and systems of inequalities as half-planes."}]},{"n":19,"title":"Algebra I: Exponents, Polynomials and Quadratics","band":"Grades 9–10","strand":"Algebra","link":"/mth19","standards":[{"code":"HSN-RN.A.2","text":"Rewrite expressions using the properties of rational exponents and radicals."},{"code":"HSF-LE.A.1","text":"Distinguish situations modeled by linear functions from those modeled by exponential functions."},{"code":"HSA-APR.A.1","text":"Add, subtract and multiply polynomials, understanding they form a closed system."},{"code":"HSA-SSE.A.2","text":"Use the structure of an expression to rewrite it, as in factoring a difference of squares."},{"code":"HSA-REI.B.4","text":"Solve quadratic equations by inspection, square roots, completing the square, the formula and factoring."},{"code":"HSF-IF.C.7","text":"Graph functions and show key features such as intercepts, maxima and minima."}]},{"n":20,"title":"Geometry: Reasoning, Congruence and Triangles","band":"Grades 9–10","strand":"Geometry","link":"/mth20","standards":[{"code":"HSG-CO.B.6","text":"Use rigid motions to decide whether two figures are congruent."},{"code":"HSG-CO.B.8","text":"Explain how the ASA, SAS and SSS criteria follow from the definition of congruence."},{"code":"HSG-CO.C.9","text":"Prove theorems about lines and angles, including those about parallel lines and a transversal."},{"code":"HSG-CO.C.10","text":"Prove theorems about triangles, such as angle sum, base angles and the midsegment theorem."},{"code":"HSG-CO.C.11","text":"Prove theorems about parallelograms and their sides, angles and diagonals."},{"code":"HSG-CO.D.12","text":"Make formal geometric constructions with compass and straightedge or other tools."}]},{"n":21,"title":"Geometry: Similarity, Trigonometry and Circles","band":"Grades 9–10","strand":"Geometry","link":"/mth21","standards":[{"code":"HSG-SRT.A.2","text":"Use similarity transformations to decide whether two figures are similar."},{"code":"HSG-SRT.B.5","text":"Use congruence and similarity criteria to solve problems and prove relationships in figures."},{"code":"HSG-SRT.C.8","text":"Use trigonometric ratios and the Pythagorean theorem to solve right triangles in applied problems."},{"code":"HSG-C.A.2","text":"Identify and use relationships among inscribed angles, radii, chords and tangents."},{"code":"HSG-C.B.5","text":"Derive arc length and sector area and define the radian measure of an angle."},{"code":"HSG-GMD.A.3","text":"Use volume formulas for cylinders, pyramids, cones and spheres to solve problems."}]},{"n":22,"title":"Statistics in Algebra I","band":"Grades 9–10","strand":"Statistics","link":"/mth22","standards":[{"code":"HSS-ID.A.1","text":"Represent data with dot plots, histograms and box plots."},{"code":"HSS-ID.A.2","text":"Compare center and spread of two or more data sets using appropriate statistics."},{"code":"HSS-ID.B.5","text":"Summarize categorical data in two-way frequency tables and interpret relative frequencies."},{"code":"HSS-ID.B.6","text":"Fit a function to two-variable data and assess the fit by plotting residuals."},{"code":"HSS-ID.C.8","text":"Compute and interpret the correlation coefficient of a linear fit using technology."},{"code":"HSS-ID.C.9","text":"Distinguish between correlation and causation."}]},{"n":23,"title":"Algebra II: Polynomial, Rational and Radical Functions","band":"Grades 11–12","strand":"Algebra","link":"/mth23","standards":[{"code":"HSN-CN.C.9","text":"Know the fundamental theorem of algebra and show it holds for quadratic polynomials."},{"code":"HSA-APR.B.2","text":"Know and apply the remainder theorem when dividing polynomials."},{"code":"HSA-APR.B.3","text":"Find zeros of polynomials by factoring and use them to sketch a rough graph."},{"code":"HSA-APR.D.6","text":"Rewrite rational expressions in different forms using inspection, long division or technology."},{"code":"HSA-REI.A.2","text":"Solve rational and radical equations and identify extraneous solutions."},{"code":"HSF-BF.B.4","text":"Find inverse functions and write an expression for the inverse."}]},{"n":24,"title":"Algebra II: Exponential, Logarithmic and Trigonometric Functions","band":"Grades 11–12","strand":"Algebra","link":"/mth24","standards":[{"code":"HSF-LE.A.4","text":"Express solutions to exponential equations as logarithms and evaluate them with technology."},{"code":"HSF-LE.B.5","text":"Interpret the parameters of a linear or exponential function in context."},{"code":"HSF-TF.A.1","text":"Understand radian measure as the arc length subtended on the unit circle."},{"code":"HSF-TF.A.2","text":"Use the unit circle to extend trigonometric functions to all real numbers."},{"code":"HSF-TF.B.5","text":"Model periodic phenomena with trigonometric functions using amplitude, frequency and midline."},{"code":"HSF-TF.C.8","text":"Prove the Pythagorean identity and use it to find trigonometric values."}]},{"n":25,"title":"Sequences, Series and Modeling","band":"Grades 11–12","strand":"Algebra and Modeling","link":"/mth25","standards":[{"code":"HSF-IF.A.3","text":"Recognize sequences as functions, sometimes defined recursively, on a subset of the integers."},{"code":"HSF-BF.A.2","text":"Write arithmetic and geometric sequences recursively and explicitly and use them to model."},{"code":"HSA-SSE.B.4","text":"Derive the formula for the sum of a finite geometric series and apply it to problems."},{"code":"HSF-BF.A.1","text":"Build a function that models a relationship, including by combining functions."},{"code":"HSF-BF.B.3","text":"Describe the effect of transformations such as f(x) + k and f(kx) on a graph."},{"code":"HSS-ID.B.6","text":"Fit a function to data, use it to solve problems and assess the fit."}]},{"n":26,"title":"Statistics: From a Sample to a Claim","band":"Grades 11–12","strand":"Statistics and Probability","link":"/mth26","standards":[{"code":"HSS-ID.A.4","text":"Use the mean and standard deviation of a normal distribution to estimate percentages."},{"code":"HSS-CP.A.4","text":"Build two-way frequency tables and use them to decide independence and find conditional probabilities."},{"code":"HSS-IC.A.1","text":"Understand statistics as making inferences about a population from a random sample."},{"code":"HSS-IC.B.3","text":"Recognize the purposes of and differences among surveys, experiments and observational studies."},{"code":"HSS-IC.B.4","text":"Use sample data to estimate a population parameter and develop a margin of error with simulation."},{"code":"HSS-IC.B.6","text":"Evaluate reports based on data."}]},{"n":27,"title":"Financial Math and Capstone","band":"Grades 11–12","strand":"Applied Mathematics","link":"/mth27","standards":[{"code":"HSA-SSE.B.4","text":"Use the geometric-series formula to solve problems such as computing loan payments."},{"code":"HSF-LE.A.1","text":"Recognize when a quantity grows by a constant rate versus a constant percent, as with interest."},{"code":"HSF-LE.B.5","text":"Interpret the parameters of a linear or exponential model in a financial context."},{"code":"HSN-Q.A.1","text":"Use units to guide the solution of multi-step problems and to interpret graphs and data displays."},{"code":"HSN-Q.A.3","text":"Choose a level of accuracy appropriate to the limits of measurement when reporting quantities."},{"code":"HSA-CED.A.3","text":"Represent constraints with equations or inequalities and interpret solutions in a modeling context."}]}],"codes":162},{"key":"ela","name":"English Language Arts","subject":"K–12 · 24 units","hub":"/english-course","hubExists":true,"framework":{"name":"Illinois Learning Standards for English Language Arts (Common Core State Standards for ELA/Literacy)","short":"IL ELA / CCSS","note":"Codes name a strand, grade or grade band, and standard number (e.g. RL.3.1, W.9-10.7); the alignment was made by the course author and is not a certification by any agency."},"units":[{"n":1,"title":"Sounds and Letters","band":"Grades K–2","strand":"Foundations","link":"/ela1","standards":[{"code":"RF.K.2","text":"Hear and work with rhymes, syllables, and the separate sounds inside spoken words."},{"code":"RF.1.2","text":"Blend and segment the individual sounds in spoken one-syllable words, including short vowels."},{"code":"RF.K.1","text":"Know how print works: left to right, top to bottom, letters make words, upper and lower case."},{"code":"RF.K.3","text":"Match each consonant and short vowel to its sound and read a few high-frequency words."},{"code":"RF.1.3","text":"Use letter-sound knowledge, digraphs, and final-e patterns to decode one-syllable words."},{"code":"L.K.1","text":"Print many upper and lowercase letters and use frequently occurring words when speaking and writing."}]},{"n":2,"title":"Words and Sentences","band":"Grades K–2","strand":"Foundations and Language","link":"/ela2","standards":[{"code":"RF.1.3","text":"Decode regular words, common digraphs, inflectional endings, and irregularly spelled sight words."},{"code":"RF.2.3","text":"Use vowel patterns, prefixes, suffixes, and sight-word knowledge to read grade-level words."},{"code":"RF.1.4","text":"Read grade-level text accurately, at a good pace, and with expression, rereading as needed."},{"code":"L.1.1","text":"Use nouns, verbs, adjectives, and word order to produce complete telling, asking, and exclaiming sentences."},{"code":"L.K.2","text":"Capitalize the first word of a sentence and the word I, and end sentences with punctuation."},{"code":"L.1.2","text":"Capitalize dates and names, use end punctuation, and spell common words correctly in writing."}]},{"n":3,"title":"Stories and True Books","band":"Grades K–2","strand":"Reading","link":"/ela3","standards":[{"code":"RL.K.3","text":"Name the characters, settings, and major events in a story with prompting and support."},{"code":"RL.2.1","text":"Ask and answer who, what, where, when, why, and how questions about a story's key details."},{"code":"RL.2.2","text":"Retell stories, fables, and folktales and state the lesson or message they teach."},{"code":"RL.2.9","text":"Compare two versions of the same story told by different authors or from different cultures."},{"code":"RI.1.2","text":"Identify the main topic of an informational text and retell its key details."},{"code":"RI.2.5","text":"Use headings, captions, tables of contents, glossaries, and other features to find information."}]},{"n":4,"title":"Writing and Telling","band":"Grades K–2","strand":"Writing and Speaking","link":"/ela4","standards":[{"code":"W.1.3","text":"Write a narrative that recounts two or more events in order using words like first and next."},{"code":"W.1.1","text":"Write an opinion about a topic or book, give a reason, and add a closing."},{"code":"W.1.2","text":"Write an informative piece that names a topic, gives facts about it, and closes."},{"code":"SL.1.1","text":"Take part in conversations with peers and adults, follow turn-taking rules, and ask questions."},{"code":"SL.2.4","text":"Tell a story or recount an experience with relevant details, speaking clearly in complete sentences."},{"code":"L.1.6","text":"Use words and phrases learned from conversations, reading, and being read to."}]},{"n":5,"title":"Word Power","band":"Grades 3–5","strand":"Language and Vocabulary","link":"/ela5","standards":[{"code":"RF.3.3","text":"Decode words using common prefixes, suffixes, Latin suffixes, and multisyllable patterns."},{"code":"L.3.4","text":"Use sentence context, known affixes and roots, and glossaries to figure out unknown words."},{"code":"L.4.4","text":"Use context, Greek and Latin affixes and roots, and reference materials to find word meanings."},{"code":"L.5.4","text":"Determine the meaning of unfamiliar words through context, Greek and Latin roots, and reference tools."},{"code":"L.5.5","text":"Interpret similes, metaphors, and idioms and understand relationships among synonyms and antonyms."},{"code":"L.4.6","text":"Acquire and use grade-appropriate academic and topic-specific words, including signal words."}]},{"n":6,"title":"Reading Stories","band":"Grades 3–5","strand":"Literature","link":"/ela6","standards":[{"code":"RL.3.2","text":"Recount fables, folktales, and myths from diverse cultures and explain the central message."},{"code":"RL.3.3","text":"Describe a character's traits, motivations, and feelings and how actions affect the sequence of events."},{"code":"RL.4.1","text":"Use details and examples from the text to explain what it says directly and to draw inferences."},{"code":"RL.5.2","text":"Determine a theme from how characters respond to challenges and summarize the text."},{"code":"RL.5.6","text":"Describe how a narrator's or speaker's point of view shapes the way events are described."},{"code":"RL.4.5","text":"Explain differences among poems, drama, and prose using their structural elements when writing or speaking."}]},{"n":7,"title":"Reading to Learn","band":"Grades 3–5","strand":"Informational Text","link":"/ela7","standards":[{"code":"RI.4.2","text":"Determine the main idea of a text, explain how details support it, and summarize."},{"code":"RI.3.5","text":"Use text features and search tools such as headings, key words, and sidebars to locate information."},{"code":"RI.4.5","text":"Describe the overall structure of a text: chronology, comparison, cause and effect, or problem and solution."},{"code":"RI.4.8","text":"Explain how an author uses reasons and evidence to support particular points in a text."},{"code":"RI.4.7","text":"Interpret charts, graphs, diagrams, timelines, and other visual information and explain how they help."},{"code":"W.4.8","text":"Gather information from sources, take notes, categorize them, and provide a list of sources."}]},{"n":8,"title":"Writing","band":"Grades 3–5","strand":"Writing","link":"/ela8","standards":[{"code":"W.4.1","text":"Write an opinion piece with a clear point of view, ordered reasons, linking words, and a conclusion."},{"code":"W.4.2","text":"Write an informative text that introduces a topic, groups related facts, and uses precise language."},{"code":"W.4.3","text":"Write a narrative with a situation, dialogue, description, transitions, sensory details, and a conclusion."},{"code":"W.5.5","text":"Develop and strengthen writing through planning, revising, editing, and rewriting with guidance."},{"code":"W.4.9","text":"Draw evidence from literary or informational texts to support analysis and reflection in writing."},{"code":"L.3.2","text":"Use capitals in titles, commas in addresses, and quotation marks in dialogue; apply spelling patterns."}]},{"n":9,"title":"Grammar, Speaking and Listening","band":"Grades 3–5","strand":"Language and Speaking","link":"/ela9","standards":[{"code":"L.3.1","text":"Explain the function of nouns, verbs, adjectives, and adverbs and produce simple, compound, and complex sentences."},{"code":"L.4.1","text":"Use correct verb tenses and modifiers, order adjectives, fix fragments and run-ons, and use homophones correctly."},{"code":"L.4.3","text":"Choose precise words and punctuation for effect and know when formal English is expected."},{"code":"SL.4.1","text":"Come prepared to discussions, follow agreed rules, ask and answer questions, and build on others' remarks."},{"code":"SL.4.2","text":"Paraphrase portions of information presented aloud or in other media formats."},{"code":"SL.4.4","text":"Report on a topic or tell a story in an organized way with facts and details, speaking at an understandable pace."}]},{"n":10,"title":"The Novel","band":"Grades 6–8","strand":"Literature","link":"/ela10","standards":[{"code":"RL.8.1","text":"Cite the textual evidence that most strongly supports what a text says and the inferences drawn."},{"code":"RL.7.3","text":"Analyze how particular elements of a story interact, such as how setting shapes characters or plot."},{"code":"RL.8.6","text":"Analyze how differences between characters' and readers' points of view create suspense or dramatic irony."},{"code":"RL.8.2","text":"Determine a theme and analyze its development through characters, setting, and plot; summarize objectively."},{"code":"RL.7.7","text":"Compare a written story to its audio, film, or staged version and analyze the medium's effects."},{"code":"RL.6.10","text":"Read and comprehend a range of stories, dramas, and poems at grade-level complexity independently."}]},{"n":11,"title":"Nonfiction and Argument","band":"Grades 6–8","strand":"Informational Text","link":"/ela11","standards":[{"code":"RI.7.2","text":"Determine two or more central ideas, trace their development, and write an objective summary."},{"code":"RI.8.4","text":"Determine word meanings in a text and analyze how specific word choices affect meaning and tone."},{"code":"RI.7.9","text":"Analyze how two or more authors writing about the same topic shape their presentations differently."},{"code":"RI.8.8","text":"Trace and evaluate an argument, judging whether the reasoning is sound and the evidence relevant and sufficient."},{"code":"W.7.1","text":"Write arguments with clear claims, acknowledgment of opposing claims, logical reasoning, and relevant evidence."},{"code":"W.7.8","text":"Gather information from credible sources, quote or paraphrase without plagiarizing, and cite in a standard format."}]},{"n":12,"title":"Words: Stems and Meaning","band":"Grades 6–8","strand":"Vocabulary","link":"/ela12","standards":[{"code":"L.6.4","text":"Use context, Greek and Latin affixes and roots, and reference materials to determine word meanings."},{"code":"L.7.4","text":"Determine the meaning of unknown words using context, common roots and affixes, and reference tools."},{"code":"L.6.5","text":"Interpret figures of speech, understand word relationships, and distinguish connotations of similar words."},{"code":"L.8.5","text":"Interpret figures of speech such as verbal irony and puns and distinguish among words' connotations."},{"code":"RL.7.4","text":"Determine figurative and connotative meanings in a text and analyze the effect of sound devices."},{"code":"L.7.6","text":"Acquire and use academic and domain-specific words and gather vocabulary knowledge when needed."}]},{"n":13,"title":"Grammar and Style","band":"Grades 6–8","strand":"Language","link":"/ela13","standards":[{"code":"L.6.1","text":"Use pronouns correctly in case, number, and person and recognize and correct inappropriate pronoun shifts."},{"code":"L.7.1","text":"Explain the function of phrases and clauses, use varied sentence types, and place modifiers correctly."},{"code":"L.8.1","text":"Explain the function of verbals, form and use active and passive voice, and use verb moods correctly."},{"code":"L.6.2","text":"Use commas, parentheses, or dashes to set off nonrestrictive elements and spell correctly."},{"code":"L.7.2","text":"Use a comma between coordinate adjectives and spell grade-appropriate words correctly."},{"code":"L.8.2","text":"Use a comma, ellipsis, or dash to indicate a pause or break and an ellipsis to show an omission."}]},{"n":14,"title":"Writing Across Forms","band":"Grades 6–8","strand":"Writing","link":"/ela14","standards":[{"code":"W.8.1","text":"Write arguments that introduce claims, address counterclaims, organize reasons logically, and use formal style."},{"code":"W.8.2","text":"Write informative texts that introduce and organize ideas with relevant facts, transitions, and precise language."},{"code":"W.8.3","text":"Write narratives using dialogue, pacing, description, and reflection, with a conclusion that follows from events."},{"code":"W.8.5","text":"Plan, revise, edit, rewrite, or try a new approach with guidance, focusing on purpose and audience."},{"code":"W.8.9","text":"Draw evidence from literary or informational texts to support analysis, reflection, and research."},{"code":"W.8.10","text":"Write routinely over extended and shorter time frames for a range of tasks, purposes, and audiences."}]},{"n":15,"title":"Literature: Close Reading","band":"Grades 9–10","strand":"Literature","link":"/ela15","standards":[{"code":"RL.9-10.1","text":"Cite strong and thorough textual evidence for explicit statements and inferences drawn from a text."},{"code":"RL.9-10.2","text":"Determine a theme and analyze in detail how it emerges and is shaped by specific details."},{"code":"RL.9-10.3","text":"Analyze how complex characters with conflicting motivations develop, interact, and advance the theme."},{"code":"RL.9-10.4","text":"Analyze the cumulative effect of specific word choices on meaning and tone, including formal or informal tone."},{"code":"RL.9-10.5","text":"Analyze how an author's structural choices, such as pacing and flashbacks, create effects like tension or surprise."},{"code":"RL.9-10.7","text":"Analyze a subject or scene as represented in two different artistic mediums, noting what each emphasizes."}]},{"n":16,"title":"The Language of Persuasion","band":"Grades 9–10","strand":"Rhetoric","link":"/ela16","standards":[{"code":"RI.9-10.4","text":"Analyze the cumulative impact of specific word choices on the meaning and tone of a text."},{"code":"RI.9-10.6","text":"Determine an author's point of view or purpose and analyze how rhetoric advances that purpose."},{"code":"RI.9-10.8","text":"Delineate and evaluate an argument's claims, reasoning, and evidence, identifying false statements and fallacies."},{"code":"RI.9-10.9","text":"Analyze seminal U.S. documents of historical and literary significance and how they address related themes."},{"code":"W.9-10.1","text":"Write arguments with precise claims, fairly developed counterclaims, valid reasoning, and a formal style."},{"code":"SL.9-10.3","text":"Evaluate a speaker's point of view, reasoning, and use of evidence and rhetoric, noting fallacious reasoning."}]},{"n":17,"title":"Words and Structure","band":"Grades 9–10","strand":"Vocabulary","link":"/ela17","standards":[{"code":"L.9-10.4","text":"Determine word meanings using context, patterns of word changes, and reference materials including etymology."},{"code":"L.9-10.5","text":"Interpret figures of speech such as euphemism and oxymoron and analyze their role in a text."},{"code":"L.9-10.6","text":"Acquire and use academic and domain-specific words and phrases sufficient for college and career readiness."},{"code":"RL.9-10.4","text":"Determine figurative and connotative meanings of words and analyze their effect on meaning and tone."}]},{"n":18,"title":"Grammar for Writers","band":"Grades 9–10","strand":"Language","link":"/ela18","standards":[{"code":"L.9-10.1","text":"Use parallel structure and various types of phrases and clauses to convey meaning and add variety."},{"code":"L.9-10.2","text":"Use semicolons and colons correctly to link related independent clauses and spell correctly."},{"code":"L.9-10.3","text":"Apply language knowledge in context and follow the guidelines in a style manual when writing."},{"code":"W.9-10.5","text":"Develop and strengthen writing by planning, revising, editing, and rewriting for purpose and audience."},{"code":"W.9-10.4","text":"Produce clear, coherent writing whose development, organization, and style fit the task and audience."}]},{"n":19,"title":"Research and Writing","band":"Grades 9–10","strand":"Writing","link":"/ela19","standards":[{"code":"W.9-10.7","text":"Conduct short and sustained research projects to answer a question, synthesizing multiple sources."},{"code":"W.9-10.8","text":"Gather relevant sources, assess their usefulness, integrate information without plagiarizing, and cite them."},{"code":"W.9-10.9","text":"Draw evidence from literary or informational texts to support analysis, reflection, and research."},{"code":"W.9-10.2","text":"Write informative texts that examine complex ideas through effective organization, evidence, and precise language."},{"code":"W.9-10.3","text":"Write narratives using effective technique, well-chosen details, and well-structured event sequences."},{"code":"W.9-10.5","text":"Strengthen writing through planning, revising, editing, and rewriting, focusing on what matters most for the purpose."}]},{"n":20,"title":"Literary Devices and American Voices","band":"Grades 11–12","strand":"Literature","link":"/ela20","standards":[{"code":"RL.11-12.1","text":"Cite strong textual evidence, including where the text leaves matters uncertain."},{"code":"RL.11-12.2","text":"Determine two or more themes and analyze how they interact and build to produce a complex account."},{"code":"RL.11-12.3","text":"Analyze the impact of an author's choices about setting, event order, and character development."},{"code":"RL.11-12.5","text":"Analyze how choices about structure, such as where to begin or end, contribute to meaning and aesthetic impact."},{"code":"RL.11-12.6","text":"Analyze a point of view requiring distinction between what is stated and what is meant, as in satire or irony."},{"code":"RL.11-12.9","text":"Show knowledge of foundational American literature and how two or more texts treat similar themes or topics."}]},{"n":21,"title":"Diction, Syntax and Style","band":"Grades 11–12","strand":"Language","link":"/ela21","standards":[{"code":"L.11-12.3","text":"Apply language knowledge to understand how it works in context and vary syntax for effect."},{"code":"RL.11-12.4","text":"Analyze word choices with multiple meanings and language that is especially fresh, engaging, or beautiful."},{"code":"RI.11-12.6","text":"Analyze how an author's style and content contribute to the power, persuasiveness, or beauty of a text."},{"code":"W.11-12.4","text":"Produce clear, coherent writing whose development, organization, and style fit task, purpose, and audience."},{"code":"W.11-12.5","text":"Strengthen writing by revising, editing, and rewriting, addressing what is most significant for the purpose."}]},{"n":22,"title":"Reasoning and Argument","band":"Grades 11–12","strand":"Argument","link":"/ela22","standards":[{"code":"RI.11-12.6","text":"Determine an author's point of view or purpose in a text where the rhetoric is especially effective."},{"code":"RI.11-12.7","text":"Integrate and evaluate multiple sources of information, including quantitative data, to address a question."},{"code":"RI.11-12.8","text":"Delineate and evaluate the reasoning in seminal U.S. texts, including constitutional principles and public advocacy."},{"code":"RI.11-12.9","text":"Analyze foundational U.S. documents such as the Declaration, Preamble, and Bill of Rights for themes and rhetoric."},{"code":"W.11-12.1","text":"Write arguments with precise, knowledgeable claims, counterclaims, valid reasoning, and sufficient evidence."},{"code":"SL.11-12.3","text":"Evaluate a speaker's reasoning, evidence, stance, premises, and links among ideas, noting tone and word choice."}]},{"n":23,"title":"Advanced Grammar and Usage","band":"Grades 11–12","strand":"Language","link":"/ela23","standards":[{"code":"L.11-12.1","text":"Understand that usage is a matter of convention that can change and resolve contested usage with references."},{"code":"L.11-12.2","text":"Observe hyphenation conventions and spell correctly when writing."},{"code":"L.11-12.3","text":"Vary syntax for effect and consult references for guidance when reading complex texts."},{"code":"W.11-12.4","text":"Produce writing whose development, organization, and style are appropriate to task, purpose, and audience."},{"code":"W.11-12.5","text":"Plan, revise, edit, and rewrite, focusing on what is most significant for a specific purpose and audience."}]},{"n":24,"title":"Capstone: Research, Cite, Defend","band":"Grades 11–12","strand":"Research","link":"/ela24","standards":[{"code":"W.11-12.7","text":"Conduct sustained research projects, narrowing or broadening the inquiry and synthesizing multiple sources."},{"code":"W.11-12.8","text":"Gather authoritative sources, assess their strengths and limitations, avoid overreliance on one source, and cite properly."},{"code":"W.11-12.1","text":"Write arguments that support substantive claims with valid reasoning and relevant, sufficient evidence."},{"code":"SL.11-12.1","text":"Lead collaborative discussions, probe reasoning and evidence, resolve contradictions, and synthesize comments."},{"code":"SL.11-12.4","text":"Present information and evidence so listeners can follow the reasoning, addressing alternative perspectives."},{"code":"SL.11-12.5","text":"Make strategic use of digital media in presentations to enhance understanding and add interest."}]}],"codes":139},{"key":"ss","name":"Social Studies","subject":"K–12 · 24 units","hub":"/social-studies-course","hubExists":true,"framework":{"name":"Illinois Learning Standards for Social Science","short":"IL SS","note":"Codes are Illinois Learning Standards for Social Science (2016, revised 2022, built on the C3 Framework) by strand (CV, G, EC, H, IS) and grade or band; alignment was made by the course author and is not a certification."},"units":[{"n":1,"title":"Me, My Family, My School","band":"Grades K–2","strand":"Civics and History","link":"/ssc1","standards":[{"code":"SS.CV.2.K","text":"Explain why rules are needed and what they are for at school and elsewhere"},{"code":"SS.CV.1.K","text":"Describe what people in authority, like teachers and principals, do and are responsible for"},{"code":"SS.CV.2.1","text":"Identify rules and explain how they work in different settings in and out of school"},{"code":"SS.CV.1.1","text":"Explain that everyone in a community, not only leaders, has an important role"},{"code":"SS.IS.6.K-2","text":"Use listening, consensus and voting to make decisions and act together in class"}]},{"n":2,"title":"Our Community","band":"Grades K–2","strand":"Civics and Economics","link":"/ssc2","standards":[{"code":"SS.CV.2.2","text":"Describe how a community works together on shared tasks and assigns roles and responsibilities"},{"code":"SS.G.2.1","text":"Identify features of your own community and compare them with other places"},{"code":"SS.EC.1.K","text":"Explain that people make choices because they cannot have everything they want"},{"code":"SS.EC.1.1","text":"Explain and summarize the choices people make to meet their needs and wants"},{"code":"SS.EC.2.1","text":"Describe the skills and knowledge needed to produce particular goods and services"},{"code":"SS.EC.FL.1.1","text":"Explain that people earn pay or income in exchange for the work they do"}]},{"n":3,"title":"Maps and Places","band":"Grades K–2","strand":"Geography","link":"/ssc3","standards":[{"code":"SS.G.1.1","text":"Make and read maps and other representations to find your way around a familiar place"},{"code":"SS.G.1.2","text":"Construct and interpret maps and graphics of familiar and unfamiliar places"},{"code":"SS.G.2.2","text":"Identify cultural and environmental characteristics of specific places"},{"code":"SS.G.1.K","text":"Explain how weather, climate and other environmental features affect how people live"}]},{"n":4,"title":"Then and Now, and Our Country","band":"Grades K–2","strand":"History and Civics","link":"/ssc4","standards":[{"code":"SS.H.1.K","text":"Compare how people lived in the past with how they live today"},{"code":"SS.H.1.2","text":"Summarize how the local community has changed over time"},{"code":"SS.H.3.2","text":"Explain how documents, objects, pictures and oral accounts can be used to study the past"},{"code":"SS.H.2.K","text":"Explain what national holidays mean and the people and achievements they honor"},{"code":"SS.H.2.1","text":"Describe individuals and groups who brought about important historical change"},{"code":"SS.IS.6.K-2","text":"Use listening, consensus and voting to make decisions and act together in class"}]},{"n":5,"title":"Illinois: Land and People","band":"Grades 3–5","strand":"Geography and History","link":"/ssc5","standards":[{"code":"SS.G.1.4","text":"Construct and interpret maps of Illinois and the United States in various media"},{"code":"SS.G.2.4","text":"Analyze how the cultural and environmental features of Illinois places change over time"},{"code":"SS.G.1.3","text":"Locate major landforms and bodies of water on a map or other representation"},{"code":"SS.H.2.4","text":"Use artifacts and primary sources to investigate how people contributed to founding and developing Illinois"},{"code":"SS.H.3.4","text":"Explain probable causes and effects of events and developments in Illinois history"}]},{"n":6,"title":"The First Peoples of North America","band":"Grades 3–5","strand":"History and Geography","link":"/ssc6","standards":[{"code":"SS.H.1.4","text":"Explain historical contexts and why groups in the same period held different perspectives"},{"code":"SS.G.2.3","text":"Compare how people adapt to and modify their environment in different places"},{"code":"SS.H.3.5","text":"Explain likely causes and effects of events and developments in U.S. history"},{"code":"SS.H.2.5","text":"Judge how useful a historical source is by its maker, date, origin, audience and purpose"},{"code":"SS.IS.3.3-5","text":"Find sources with multiple points of view to help answer essential questions"}]},{"n":7,"title":"Colonies to a New Nation","band":"Grades 3–5","strand":"U.S. History","link":"/ssc7","standards":[{"code":"SS.H.3.5","text":"Explain likely causes and effects of events and developments in U.S. history"},{"code":"SS.H.1.5","text":"Build and use a timeline of related events to compare developments of the same period"},{"code":"SS.CV.2.5","text":"Examine where rules, laws and key U.S. constitutional provisions come from and why"},{"code":"SS.CV.3.5","text":"Compare the origins, functions and structure of different systems of government"},{"code":"SS.H.1.4","text":"Explain historical contexts and why groups in the same period held different perspectives"},{"code":"SS.G.1.5","text":"Investigate how the cultural and environmental characteristics of U.S. places change over time"}]},{"n":8,"title":"Government: Local, State, National","band":"Grades 3–5","strand":"Civics","link":"/ssc8","standards":[{"code":"SS.CV.1.4","text":"Distinguish the powers and responsibilities of local, state and national government officials"},{"code":"SS.CV.2.4","text":"Explain how democracy depends on responsible participation and how individuals should take part"},{"code":"SS.CV.3.4","text":"Identify civic virtues and democratic principles that guide Illinois and the nation"},{"code":"SS.CV.4.4","text":"Explain how rules and laws change society and how people change laws in Illinois"},{"code":"SS.CV.4.5","text":"Explain how policies are developed to address public problems"},{"code":"SS.IS.7.3-5","text":"Identify local problems and some of the ways people are working to address them"}]},{"n":9,"title":"Money, Markets and Regions","band":"Grades 3–5","strand":"Economics and Geography","link":"/ssc9","standards":[{"code":"SS.EC.1.5","text":"Analyze why and how individuals, businesses and nations specialize and trade"},{"code":"SS.EC.2.4","text":"Describe how goods and services are made using human, natural and capital resources"},{"code":"SS.EC.3.5","text":"Determine how government pays for the goods and services it provides"},{"code":"SS.EC.FL.2.4","text":"Explain that income can be saved, spent on goods and services or used to pay taxes"},{"code":"SS.G.2.5","text":"Describe how people have used natural resources across the United States"},{"code":"SS.G.1.5","text":"Investigate how the cultural and environmental characteristics of U.S. places change over time"}]},{"n":10,"title":"The First Civilizations","band":"Grades 6–8","strand":"World History","link":"/ssc10","standards":[{"code":"SS.H.1.6-8.LC","text":"Classify historical events and developments as examples of change or continuity"},{"code":"SS.H.3.6-8.LC","text":"Classify the kinds of historical sources used in secondary interpretations"},{"code":"SS.H.3.6-8.MdC","text":"Detect possible gaps in the historical record from different kinds of sources"},{"code":"SS.G.2.6-8.LC","text":"Explain how humans and their environment affect one another"},{"code":"SS.H.4.6-8.LC","text":"Explain multiple causes and effects of historical events"}]},{"n":11,"title":"Classical Worlds","band":"Grades 6–8","strand":"World History","link":"/ssc11","standards":[{"code":"SS.H.1.6-8.MdC","text":"Analyze connections among events and developments within broader historical contexts"},{"code":"SS.H.2.6-8.MdC","text":"Analyze the many factors that shaped people's perspectives in different eras"},{"code":"SS.CV.2.6-8.LC","text":"Describe the origins, purposes and impact of constitutions, laws and treaties"},{"code":"SS.G.3.6-8.MdC","text":"Explain how transportation and communication changes spread ideas and connect settlements"},{"code":"SS.H.4.6-8.LC","text":"Explain multiple causes and effects of historical events"}]},{"n":12,"title":"Faiths, Empires and Exchange","band":"Grades 6–8","strand":"World History","link":"/ssc12","standards":[{"code":"SS.H.1.6-8.MdC","text":"Analyze connections among events and developments within broader historical contexts"},{"code":"SS.G.3.6-8.MdC","text":"Explain how transportation and communication changes spread ideas and connect settlements"},{"code":"SS.G.4.6-8.LC","text":"Identify how cultural and environmental characteristics vary among world regions"},{"code":"SS.H.2.6-8.LC","text":"Explain how and why people's perspectives have changed over time"},{"code":"SS.H.4.6-8.MdC","text":"Compare the central arguments of several secondary works on related historical topics"}]},{"n":13,"title":"Geography of the World","band":"Grades 6–8","strand":"Geography","link":"/ssc13","standards":[{"code":"SS.G.1.6-8.LC","text":"Use maps, photographs and satellite images to explain links between location and environmental change"},{"code":"SS.G.1.6-8.MdC","text":"Use mapping and graphing to analyze spatial patterns of environmental and cultural traits"},{"code":"SS.G.2.6-8.LC","text":"Explain how humans and their environment affect one another"},{"code":"SS.G.2.6-8.MC","text":"Explain how place characteristics and production of goods shape patterns of world trade"},{"code":"SS.G.3.6-8.LC","text":"Explain how environmental characteristics affect human migration and settlement"},{"code":"SS.G.4.6-8.LC","text":"Identify how cultural and environmental characteristics vary among world regions"}]},{"n":14,"title":"Citizens of Illinois","band":"Grades 6–8","strand":"Civics","link":"/ssc14","standards":[{"code":"SS.CV.1.6-8.LC","text":"Identify roles citizens play, such as voters, jurors, taxpayers, protesters and officeholders"},{"code":"SS.CV.1.6-8.MC","text":"Evaluate the powers and responsibilities of citizens, parties, interest groups and the media"},{"code":"SS.CV.2.6-8.MdC","text":"Explain the origins, functions and structure of government under the U.S. and Illinois constitutions"},{"code":"SS.CV.2.6-8.MC","text":"Analyze the powers and limits of governments and officials at different levels"},{"code":"SS.CV.3.6-8.MdC","text":"Compare ways individuals and groups change society, promote the common good and protect rights"},{"code":"SS.CV.4.6-8.MdC","text":"Analyze ideas in founding documents and explain how they shape the political system"}]},{"n":15,"title":"World History: Empires and Exchange","band":"Grades 9–10","strand":"1200–1750","link":"/ssc15","standards":[{"code":"SS.H.1.9-12","text":"Evaluate how historical developments were shaped by time, place and broader contexts"},{"code":"SS.H.2.9-12","text":"Analyze change and continuity within and across historical eras"},{"code":"SS.H.4.9-12","text":"Analyze how people and institutions interacted with environmental, technological and economic developments"},{"code":"SS.H.8.9-12","text":"Analyze key events and contributions through varied perspectives, including underrepresented groups"},{"code":"SS.H.11.9-12","text":"Analyze the multiple and complex causes and effects of past events"}]},{"n":16,"title":"Revolutions and the Modern World","band":"Grades 9–10","strand":"1750–1914","link":"/ssc16","standards":[{"code":"SS.H.3.9-12","text":"Evaluate the methods people and institutions have used to promote change"},{"code":"SS.H.7.9-12","text":"Identify the roles of individuals, groups and institutions in struggles for freedom, equality and justice"},{"code":"SS.H.4.9-12","text":"Analyze how people and institutions interacted with environmental, technological and economic developments"},{"code":"SS.H.11.9-12","text":"Analyze the multiple and complex causes and effects of past events"},{"code":"SS.H.5.9-12","text":"Analyze the factors and context that shaped people's perspectives in different eras"}]},{"n":17,"title":"The Twentieth-Century World","band":"Grades 9–10","strand":"1914–Present","link":"/ssc17","standards":[{"code":"SS.H.11.9-12","text":"Analyze the multiple and complex causes and effects of past events"},{"code":"SS.H.1.9-12","text":"Evaluate how historical developments were shaped by time, place and broader contexts"},{"code":"SS.H.7.9-12","text":"Identify the roles of individuals, groups and institutions in struggles for freedom, equality and justice"},{"code":"SS.H.2.9-12","text":"Analyze change and continuity within and across historical eras"},{"code":"SS.IS.8.9-12","text":"Use interdisciplinary lenses to trace how a problem appears at local, regional and global levels over time"}]},{"n":18,"title":"Human Geography","band":"Grades 9–10","strand":"Geography","link":"/ssc18","standards":[{"code":"SS.G.1.9-12","text":"Use geospatial technologies to build representations that explain spatial patterns"},{"code":"SS.G.2.9-12","text":"Evaluate how cultural and environmental characteristics of places and regions shape human activity"},{"code":"SS.G.3.9-12","text":"Analyze how environmental and cultural factors influence settlement, migration and interaction"},{"code":"SS.G.4.9-12","text":"Evaluate how changes in a place or region influence patterns of trade and land use"},{"code":"SS.G.8.9-12","text":"Evaluate how globalization and scarce resources drive conflict and cooperation among countries"}]},{"n":19,"title":"Civics: Rights, Power and Participation","band":"Grades 9–10","strand":"Civics","link":"/ssc19","standards":[{"code":"SS.CV.1.9-12","text":"Distinguish the rights, roles, powers and responsibilities of individuals and institutions in the political system"},{"code":"SS.CV.2.9-12","text":"Evaluate the opportunities and limits of participation in elections and the electoral process"},{"code":"SS.CV.3.9-12","text":"Analyze how constitutions, laws and agreements sustain order, justice, equality and liberty"},{"code":"SS.CV.4.9-12","text":"Explain how the Constitution created a government whose powers and limits have changed and remain contested"},{"code":"SS.CV.5.9-12","text":"Analyze how personal interest and diverse perspectives affect civic dispositions and constitutional rights"},{"code":"SS.CV.6.9-12","text":"Describe how parties, media and interest groups both influence and reflect political interests"}]},{"n":20,"title":"U.S. History: Industry to the Progressive Era","band":"Grades 11–12","strand":"1865–1920","link":"/ssc20","standards":[{"code":"SS.H.4.9-12","text":"Analyze how people and institutions interacted with environmental, technological and economic developments"},{"code":"SS.H.6.9-12","text":"Analyze the concept and pursuit of the American Dream"},{"code":"SS.H.7.9-12","text":"Identify the roles of individuals, groups and institutions in struggles for freedom, equality and justice"},{"code":"SS.H.8.9-12","text":"Analyze key events and contributions through varied perspectives, including underrepresented groups"},{"code":"SS.H.3.9-12","text":"Evaluate the methods people and institutions have used to promote change"}]},{"n":21,"title":"U.S. History: World Wars and the Cold War","band":"Grades 11–12","strand":"1920–1973","link":"/ssc21","standards":[{"code":"SS.H.11.9-12","text":"Analyze the multiple and complex causes and effects of past events"},{"code":"SS.H.1.9-12","text":"Evaluate how historical developments were shaped by time, place and broader contexts"},{"code":"SS.H.5.9-12","text":"Analyze the factors and context that shaped people's perspectives in different eras"},{"code":"SS.H.8.9-12","text":"Analyze key events and contributions through varied perspectives, including underrepresented groups"},{"code":"SS.H.4.9-12","text":"Analyze how people and institutions interacted with environmental, technological and economic developments"}]},{"n":22,"title":"U.S. History: Civil Rights to Today","band":"Grades 11–12","strand":"1954–Present","link":"/ssc22","standards":[{"code":"SS.H.3.9-12","text":"Evaluate the methods people and institutions have used to promote change"},{"code":"SS.H.7.9-12","text":"Identify the roles of individuals, groups and institutions in struggles for freedom, equality and justice"},{"code":"SS.H.8.9-12","text":"Analyze key events and contributions through varied perspectives, including underrepresented groups"},{"code":"SS.H.2.9-12","text":"Analyze change and continuity within and across historical eras"},{"code":"SS.H.6.9-12","text":"Analyze the concept and pursuit of the American Dream"},{"code":"SS.CV.8.9-12","text":"Analyze how individuals use and challenge laws to address public issues"}]},{"n":23,"title":"Government and Economics","band":"Grades 11–12","strand":"Civics and Economics","link":"/ssc23","standards":[{"code":"SS.CV.4.9-12","text":"Explain how the Constitution created a government whose powers and limits have changed and remain contested"},{"code":"SS.CV.6.9-12","text":"Describe how parties, media and interest groups both influence and reflect political interests"},{"code":"SS.CV.2.9-12","text":"Evaluate the opportunities and limits of participation in elections and the electoral process"},{"code":"SS.EC.1.9-12","text":"Analyze how scarcity and incentives shape the choices of consumers and producers"},{"code":"SS.EC.2.9-12","text":"Use marginal benefits and costs to argue for or against a solution to an economic issue"},{"code":"SS.EC.FL.1.9-12","text":"Weigh personal financial choices about earning, saving, borrowing and spending"}]},{"n":24,"title":"Capstone: Inquiry from the Sources","band":"Grades 11–12","strand":"Inquiry","link":"/ssc24","standards":[{"code":"SS.IS.1.9-12","text":"Address essential questions that reflect an enduring issue in the field"},{"code":"SS.IS.4.9-12","text":"Gather and evaluate sources by origin, credibility, point of view, context and corroboration"},{"code":"SS.IS.6.9-12","text":"Construct and evaluate arguments using multiple perspectives and sources on complex issues"},{"code":"SS.IS.7.9-12","text":"Present explanations and arguments to a targeted audience in varied settings"},{"code":"SS.IS.9.9-12","text":"Use deliberation and civic strategies to address a concern and take action in school or community"},{"code":"SS.H.9.9-12","text":"Analyze the relationship between historical sources and the interpretations built from them"}]}],"codes":130},{"key":"ush","name":"U.S. History","subject":"Grades 6–8 · 10 units","hub":"/us-history","hubExists":true,"framework":{"name":"Illinois Learning Standards for Social Science, Grades 6-8","short":"IL SS 6-8","note":"Codes are the Illinois Learning Standards for Social Science (history, civics, geography, economics and inquiry strands for grades 6-8); the alignment was made by the course author and is not a certification by any agency."},"units":[{"n":1,"title":"Early Encounters","band":"","strand":"Beginnings–1650","link":"/ush1","standards":[{"code":"SS.G.2.6-8.MdC","text":"Compare the cultural and environmental characteristics of different places and regions"},{"code":"SS.G.1.6-8.MC","text":"Use maps and historical data to explain routes of migration, trade and settlement"},{"code":"SS.H.4.6-8.LC","text":"Explain the multiple causes and effects of historical events"},{"code":"SS.H.2.6-8.MdC","text":"Examine the many factors that shaped how people saw their world in a given era"},{"code":"SS.H.3.6-8.MdC","text":"Spot gaps and limits in the historical record by comparing different kinds of sources"}]},{"n":2,"title":"English Settlement","band":"","strand":"1585–1763","link":"/ush2","standards":[{"code":"SS.G.2.6-8.MdC","text":"Compare the cultural and environmental characteristics of different places and regions"},{"code":"SS.EC.1.6-8.LC","text":"Explain how economic decisions affect the well-being of individuals, businesses and society"},{"code":"SS.CV.2.6-8.LC","text":"Describe where constitutions, laws, treaties and international agreements come from, what they are for, and their effects"},{"code":"SS.H.1.6-8.MdC","text":"Connect specific events and developments to the wider historical context around them"},{"code":"SS.H.2.6-8.MdC","text":"Examine the many factors that shaped how people saw their world in a given era"}]},{"n":3,"title":"A New Nation","band":"","strand":"1763–1791","link":"/ush3","standards":[{"code":"SS.H.4.6-8.LC","text":"Explain the multiple causes and effects of historical events"},{"code":"SS.CV.4.6-8.MdC","text":"Analyze the ideas and principles in the U.S. founding documents and how they shape the political system"},{"code":"SS.CV.2.6-8.MdC","text":"Explain the origins, functions and structure of government with reference to the U.S. and Illinois constitutions"},{"code":"SS.CV.1.6-8.MC","text":"Evaluate the powers and responsibilities of citizens, parties, interest groups and the media"},{"code":"SS.H.1.6-8.MC","text":"Ask questions about individuals and groups to explain why they and their achievements matter historically"},{"code":"SS.IS.3.6-8","text":"Choose sources that represent multiple points of view to help answer essential questions"}]},{"n":4,"title":"The Early Republic","band":"","strand":"1789–1844","link":"/ush4","standards":[{"code":"SS.CV.2.6-8.MC","text":"Analyze the powers and limits of governments and public officials at different levels"},{"code":"SS.CV.1.6-8.MC","text":"Evaluate the powers and responsibilities of citizens, parties, interest groups and the media"},{"code":"SS.H.4.6-8.LC","text":"Explain the multiple causes and effects of historical events"},{"code":"SS.G.1.6-8.MC","text":"Use maps and historical data to explain routes of migration, trade and settlement"},{"code":"SS.EC.1.6-8.LC","text":"Explain how economic decisions affect the well-being of individuals, businesses and society"},{"code":"SS.H.1.6-8.LC","text":"Sort historical events and developments into examples of change and of continuity"}]},{"n":5,"title":"Pushing National Boundaries","band":"","strand":"1821–1860","link":"/ush5","standards":[{"code":"SS.G.1.6-8.MC","text":"Use maps and historical data to explain routes of migration, trade and settlement"},{"code":"SS.H.4.6-8.LC","text":"Explain the multiple causes and effects of historical events"},{"code":"SS.H.2.6-8.LC","text":"Explain how and why people's viewpoints have shifted across time"},{"code":"SS.CV.3.6-8.LC","text":"Compare the ways individuals and groups change society, promote the common good and protect rights"},{"code":"SS.CV.2.6-8.LC","text":"Describe where constitutions, laws, treaties and international agreements come from, what they are for, and their effects"}]},{"n":6,"title":"Civil War and Reconstruction","band":"","strand":"1846–1877","link":"/ush6","standards":[{"code":"SS.H.4.6-8.LC","text":"Explain the multiple causes and effects of historical events"},{"code":"SS.H.1.6-8.MdC","text":"Connect specific events and developments to the wider historical context around them"},{"code":"SS.CV.2.6-8.LC","text":"Describe where constitutions, laws, treaties and international agreements come from, what they are for, and their effects"},{"code":"SS.H.2.6-8.MC","text":"Analyze how the outlook of source creators shaped what the historical record contains"},{"code":"SS.H.4.6-8.MdC","text":"Arrange relevant evidence into a coherent argument about the past"},{"code":"SS.CV.4.6-8.MdC","text":"Analyze the ideas and principles in the U.S. founding documents and how they shape the political system"}]},{"n":7,"title":"America on the Move","band":"","strand":"1860–1920","link":"/ush7","standards":[{"code":"SS.G.2.6-8.LC","text":"Explain how people and their environment affect one another"},{"code":"SS.EC.1.6-8.LC","text":"Explain how economic decisions affect the well-being of individuals, businesses and society"},{"code":"SS.CV.1.6-8.MdC","text":"Describe how political, civil and economic organizations shape people's lives"},{"code":"SS.CV.3.6-8.LC","text":"Compare the ways individuals and groups change society, promote the common good and protect rights"},{"code":"SS.H.2.6-8.MdC","text":"Examine the many factors that shaped how people saw their world in a given era"},{"code":"SS.H.1.6-8.LC","text":"Sort historical events and developments into examples of change and of continuity"}]},{"n":8,"title":"Twentieth-Century Crises","band":"","strand":"1914–1945","link":"/ush8","standards":[{"code":"SS.H.4.6-8.LC","text":"Explain the multiple causes and effects of historical events"},{"code":"SS.CV.2.6-8.MC","text":"Analyze the powers and limits of governments and public officials at different levels"},{"code":"SS.EC.1.6-8.LC","text":"Explain how economic decisions affect the well-being of individuals, businesses and society"},{"code":"SS.H.2.6-8.MC","text":"Analyze how the outlook of source creators shaped what the historical record contains"},{"code":"SS.CV.1.6-8.LC","text":"Identify the roles citizens play, such as voters, jurors, taxpayers, soldiers, protesters and officeholders"}]},{"n":9,"title":"Postwar America","band":"","strand":"1945–1973","link":"/ush9","standards":[{"code":"SS.CV.3.6-8.LC","text":"Compare the ways individuals and groups change society, promote the common good and protect rights"},{"code":"SS.CV.2.6-8.LC","text":"Describe where constitutions, laws, treaties and international agreements come from, what they are for, and their effects"},{"code":"SS.H.1.6-8.MC","text":"Ask questions about individuals and groups to explain why they and their achievements matter historically"},{"code":"SS.H.4.6-8.LC","text":"Explain the multiple causes and effects of historical events"},{"code":"SS.H.2.6-8.LC","text":"Explain how and why people's viewpoints have shifted across time"},{"code":"SS.IS.7.6-8","text":"Critique the structure and credibility of arguments and explanations, one's own and others'"}]},{"n":10,"title":"America in a Changing World","band":"","strand":"1969–Present","link":"/ush10","standards":[{"code":"SS.H.1.6-8.LC","text":"Sort historical events and developments into examples of change and of continuity"},{"code":"SS.CV.2.6-8.MC","text":"Analyze the powers and limits of governments and public officials at different levels"},{"code":"SS.CV.1.6-8.MC","text":"Evaluate the powers and responsibilities of citizens, parties, interest groups and the media"},{"code":"SS.H.4.6-8.LC","text":"Explain the multiple causes and effects of historical events"},{"code":"SS.H.3.6-8.MdC","text":"Spot gaps and limits in the historical record by comparing different kinds of sources"},{"code":"SS.H.4.6-8.MC","text":"Compare the central claims of several secondary accounts of related topics"}]}],"codes":56},{"key":"econ","name":"Economics","subject":"High school · 8 units","hub":"/economics-hub","hubExists":true,"framework":{"name":"Illinois Learning Standards for Social Science, Economics 9–12, with the Council for Economic Education Voluntary National Content Standards in Economics","short":"IL SS.EC 9–12 / CEE","note":"Codes are Illinois 9–12 economics and financial-literacy standards (SS.EC.x.9-12, SS.EC.FL.x.9-12) and CEE national content standards (CEE 1–20); alignment was made by the course author and is not a certification by either body."},"units":[{"n":1,"title":"Scarcity, Choice and Opportunity Cost","band":"Grades 9–10","strand":"","link":"/ec1","standards":[{"code":"SS.EC.1.9-12","text":"Analyze how incentives shape choices that carry different costs and benefits for different groups"},{"code":"SS.EC.2.9-12","text":"Weigh marginal benefits against marginal costs to argue for or against a solution to an economic problem"},{"code":"CEE 1","text":"Scarcity forces individuals and societies to choose among wants, giving up alternatives"},{"code":"CEE 2","text":"Sound decisions compare additional costs and benefits, and most choices are made at the margin"},{"code":"CEE 3","text":"Every allocation method, market or otherwise, has advantages and disadvantages"},{"code":"SS.EC.FL.1.9-12","text":"Explain how personal goals, education and career choices shape income and financial decisions"}]},{"n":2,"title":"Supply, Demand and the Market","band":"Grades 9–10","strand":"","link":"/ec2","standards":[{"code":"SS.EC.3.9-12","text":"Analyze how incentives determine what is produced and how it is distributed in a market system"},{"code":"CEE 4","text":"People respond predictably to positive and negative incentives"},{"code":"CEE 7","text":"Markets exist where buyers and sellers interact, and prices are set by supply and demand"},{"code":"CEE 8","text":"Prices send signals and incentives that coordinate buyers and sellers across markets"}]},{"n":3,"title":"Prices, Controls and Market Failure","band":"Grades 9–10","strand":"","link":"/ec3","standards":[{"code":"SS.EC.4.9-12","text":"Evaluate how well government policies that change market outcomes achieve their goals"},{"code":"CEE 8","text":"Price changes, including those caused by controls, reshape the incentives of buyers and sellers"},{"code":"CEE 16","text":"Government provides public goods and corrects externalities and other market failures"},{"code":"CEE 17","text":"Government intervention can also fail when costs fall on some groups and benefits go to others"},{"code":"CEE 10","text":"Institutions such as property rights, courts and contracts make markets work"}]},{"n":4,"title":"Competition, Firms and Market Structure","band":"Grades 9–10","strand":"","link":"/ec4","standards":[{"code":"SS.EC.3.9-12","text":"Analyze how competition and incentives shape what firms produce and how output is distributed"},{"code":"CEE 9","text":"The degree of competition among sellers affects prices, output and product variety"},{"code":"CEE 14","text":"Entrepreneurs take risks to organize resources and introduce new products and methods"},{"code":"CEE 10","text":"Corporations, banks and other institutions channel resources through the economy"},{"code":"CEE 13","text":"Income depends on the market value of the productive resources a person supplies"}]},{"n":5,"title":"Measuring the Economy","band":"Grades 9–10","strand":"","link":"/ec5","standards":[{"code":"SS.EC.4.9-12","text":"Use economic indicators to judge whether government policy is improving market outcomes"},{"code":"CEE 15","text":"Economic growth, measured by rising real GDP, comes from investment in physical and human capital and technology"},{"code":"CEE 19","text":"Unemployment and inflation impose real costs on individuals and the economy"},{"code":"CEE 11","text":"Inflation reduces the purchasing power of money over time"}]},{"n":6,"title":"The Business Cycle and Fiscal Policy","band":"Grades 9–10","strand":"","link":"/ec6","standards":[{"code":"SS.EC.4.9-12","text":"Evaluate the effectiveness of fiscal policies meant to change economic outcomes"},{"code":"SS.EC.2.9-12","text":"Argue for or against a policy response using marginal costs and benefits"},{"code":"CEE 18","text":"Economic fluctuations arise from changes in overall spending and production"},{"code":"CEE 20","text":"Fiscal policy uses government spending and taxes to influence output, employment and prices"},{"code":"CEE 17","text":"Political pressures can lead government policy away from economically efficient choices"}]},{"n":7,"title":"Money, Banking and the Federal Reserve","band":"Grades 9–10","strand":"","link":"/ec7","standards":[{"code":"CEE 11","text":"Money serves as a medium of exchange, unit of account and store of value"},{"code":"CEE 12","text":"Interest rates reflect the price of borrowing and reward for saving, adjusted for inflation"},{"code":"CEE 20","text":"The central bank uses monetary policy to influence interest rates, inflation and employment"},{"code":"SS.EC.FL.2.9-12","text":"Weigh the costs and benefits of different forms of credit and the effect of interest"},{"code":"SS.EC.FL.3.9-12","text":"Compare saving and investment options by expected return and risk"},{"code":"SS.EC.FL.4.9-12","text":"Evaluate ways to manage financial risk, including insurance"}]},{"n":8,"title":"Trade, Taxes and the World Economy","band":"Grades 9–10","strand":"","link":"/ec8","standards":[{"code":"SS.EC.4.9-12","text":"Evaluate how taxes and trade policies alter market outcomes"},{"code":"SS.EC.1.9-12","text":"Analyze how trade and tax policies create winners and losers among different groups"},{"code":"CEE 5","text":"Voluntary exchange benefits both parties, within a nation and across borders"},{"code":"CEE 6","text":"Specialization and comparative advantage raise output and make trade worthwhile"},{"code":"CEE 16","text":"Taxes fund government services and shift incentives for producers and consumers"}]}],"codes":40},{"key":"spa","name":"Spanish","subject":"K–12 · 20 units","hub":"/spanish-hub","hubExists":true,"framework":{"name":"ACTFL World-Readiness Standards for Learning Languages","short":"ACTFL","note":"Codes name the five goal areas (Communication, Cultures, Connections, Comparisons, Communities) and their eleven standards as ACTFL numbers them (1.1–5.2), with the ACTFL proficiency range each unit targets; the alignment is the course author's judgment, not an ACTFL certification."},"units":[{"n":1,"title":"Sounds of Spanish","band":"Grades K–2","strand":"Sounds","link":"","standards":[{"code":"ACTFL 1.2","text":"Interpretive mode: recognize and decode spoken and written Spanish sounds, syllables and first words at Novice Low."},{"code":"ACTFL 1.3","text":"Presentational mode: say and sing memorized words and short phrases (hola, adiós, the alphabet song) at Novice Low."},{"code":"ACTFL 4.1","text":"Compare the Spanish sound and spelling system (one vowel sound each, silent h, ñ, rr) with English."}]},{"n":2,"title":"Colors and Numbers","band":"Grades K–2","strand":"Numbers","link":"","standards":[{"code":"ACTFL 1.1","text":"Interpersonal mode: ask and answer ¿cuántos? and ¿de qué color es? with single words and short phrases at Novice Low/Mid."},{"code":"ACTFL 1.2","text":"Interpretive mode: understand numbers and color words in songs, games and pictures."},{"code":"ACTFL 3.1","text":"Connect to math and art by counting objects and mixing and naming colors in Spanish."},{"code":"ACTFL 4.1","text":"Notice that the color word follows the noun in Spanish, unlike English word order."}]},{"n":3,"title":"El and La: Naming Things","band":"Grades K–2","strand":"Nouns","link":"","standards":[{"code":"ACTFL 1.1","text":"Interpersonal mode: point, ask ¿Qué es? and name family members, pets and classroom objects at Novice Low/Mid."},{"code":"ACTFL 1.3","text":"Presentational mode: present one's family with simple sentences such as Esta es mi mamá."},{"code":"ACTFL 4.1","text":"Compare Spanish noun gender and articles (el, la, un, una) with English, which has none."},{"code":"ACTFL 2.1","text":"Recognize how families and homes are named and talked about in Spanish-speaking communities."}]},{"n":4,"title":"One and Many, Big and Little","band":"Grades K–2","strand":"Describing","link":"","standards":[{"code":"ACTFL 1.3","text":"Presentational mode: describe things with matching plural and adjective forms (los perros grandes) at Novice Mid."},{"code":"ACTFL 1.1","text":"Interpersonal mode: exchange simple descriptions and opposites (grande/pequeño, feliz/triste) with a partner."},{"code":"ACTFL 4.1","text":"Compare how Spanish marks plurals and adjective agreement on more than one word with English patterns."}]},{"n":5,"title":"A Whole Thought in Spanish","band":"Grades 3–5","strand":"Sentences","link":"","standards":[{"code":"ACTFL 1.1","text":"Interpersonal mode: ask and answer yes/no questions and state likes with me gusta / no me gusta at Novice Mid."},{"code":"ACTFL 1.3","text":"Presentational mode: produce whole sentences with a subject and a conjugated -ar verb."},{"code":"ACTFL 4.1","text":"Compare Spanish verb endings that show the subject, and the ¿ mark, with English question and sentence patterns."}]},{"n":6,"title":"Soy and Estoy","band":"Grades 3–5","strand":"Two Kinds of Am","link":"","standards":[{"code":"ACTFL 1.1","text":"Interpersonal mode: exchange feelings, location and origin using ¿Cómo estás? and Soy de… at Novice Mid."},{"code":"ACTFL 1.3","text":"Presentational mode: describe oneself and a friend with ser (traits, nationality) and estar (feelings, place)."},{"code":"ACTFL 4.1","text":"Compare Spanish's two verbs for to be with English's single verb."},{"code":"ACTFL 2.2","text":"Recognize nationality words and places of origin across the Spanish-speaking world."}]},{"n":7,"title":"Who, Where, When, Why","band":"Grades 3–5","strand":"Questions","link":"","standards":[{"code":"ACTFL 1.1","text":"Interpersonal mode: interview a classmate with question words and answer in full sentences at Novice Mid."},{"code":"ACTFL 1.2","text":"Interpretive mode: listen for the question word to understand what information is being asked for."},{"code":"ACTFL 2.1","text":"Use polite expressions (por favor, gracias, perdón) as practiced in Spanish-speaking cultures."},{"code":"ACTFL 4.1","text":"Compare the written accent on question words and ¿por qué? versus porque with English."}]},{"n":8,"title":"First, Then, Last: Telling a Day","band":"Grades 3–5","strand":"Sequencing","link":"","standards":[{"code":"ACTFL 1.3","text":"Presentational mode: write and read aloud a short sequenced story or comic strip of four to six sentences at Novice Mid."},{"code":"ACTFL 1.1","text":"Interpersonal mode: tell a partner about one's daily routine, days and times using sequence words."},{"code":"ACTFL 3.1","text":"Connect to ELA by applying beginning-middle-end structure and connectors to a Spanish narrative."},{"code":"ACTFL 4.1","text":"Compare how Spanish tells time (Es la una, Son las tres) with English patterns."}]},{"n":9,"title":"Greetings and Introductions","band":"Grades 6–8","strand":"Meeting People","link":"","standards":[{"code":"ACTFL 1.1","text":"Interpersonal mode: greet, introduce, spell one's name and ask ¿De dónde eres? at Novice Mid/High."},{"code":"ACTFL 2.1","text":"Practice greeting customs (handshake, cheek kiss) and tú/usted choices appropriate to Spanish-speaking cultures."},{"code":"ACTFL 2.2","text":"Understand the two-surname naming system and what it reflects about family in Hispanic cultures."},{"code":"ACTFL 4.2","text":"Compare formal and informal address and greeting customs with those of one's own culture."},{"code":"ACTFL 4.1","text":"Compare letter names and accent marks that change meaning (papá/papa) with English spelling."}]},{"n":10,"title":"Numbers, Time and Dates","band":"Grades 6–8","strand":"Numbers and Time","link":"","standards":[{"code":"ACTFL 1.1","text":"Interpersonal mode: exchange ages, prices, phone numbers, times and dates at Novice Mid/High."},{"code":"ACTFL 1.2","text":"Interpretive mode: understand spoken numbers, clock times and day-first dates."},{"code":"ACTFL 2.2","text":"Learn holidays such as Día de los Muertos and Mexican Independence Day and what they mean."},{"code":"ACTFL 3.1","text":"Connect to math by doing arithmetic aloud in Spanish (más, menos, son)."},{"code":"ACTFL 4.1","text":"Compare Spanish conventions (day-first dates, lowercase months, tener for age) with English."}]},{"n":11,"title":"The Classroom: Nouns and Articles","band":"Grades 6–8","strand":"Nouns","link":"","standards":[{"code":"ACTFL 1.1","text":"Interpersonal mode: manage classroom talk, ask for help (¿Cómo se dice? ¿Puede repetir?) and say what one needs at Novice Mid/High."},{"code":"ACTFL 1.2","text":"Interpretive mode: understand classroom commands and questions about what is in a place."},{"code":"ACTFL 3.1","text":"Name and talk about school subjects and supplies, linking Spanish to other content areas."},{"code":"ACTFL 4.1","text":"Compare noun gender and number patterns, including Greek -ma words and exceptions, with English."}]},{"n":12,"title":"Ser, Estar and Describing People","band":"Grades 6–8","strand":"Description","link":"","standards":[{"code":"ACTFL 1.3","text":"Presentational mode: describe a family member or famous person in appearance and personality at Novice High."},{"code":"ACTFL 1.1","text":"Interpersonal mode: compare people and things using más/menos… que in conversation."},{"code":"ACTFL 4.1","text":"Compare ser/estar meaning shifts and adjective placement and agreement with English usage."},{"code":"ACTFL 2.2","text":"Learn about notable people from the Spanish-speaking world through description tasks."}]},{"n":13,"title":"The Present Tense","band":"Grades 9–10","strand":"Present Tense","link":"","standards":[{"code":"ACTFL 1.1","text":"Interpersonal mode: discuss habits, routines and weekend plans (ir a + infinitive) at Intermediate Low."},{"code":"ACTFL 1.3","text":"Presentational mode: narrate present activities with regular and yo-irregular verbs in connected sentences."},{"code":"ACTFL 4.1","text":"Compare Spanish subject-pronoun dropping, vosotros/ustedes and saber versus conocer with English."},{"code":"ACTFL 2.1","text":"Recognize regional use of vosotros versus ustedes as a cultural practice."}]},{"n":14,"title":"Tener, Gustar and Stem Changes","band":"Grades 9–10","strand":"Verb Patterns","link":"","standards":[{"code":"ACTFL 1.1","text":"Interpersonal mode: express and respond to likes, needs and feelings (gustar family, tener expressions) at Intermediate Low."},{"code":"ACTFL 1.3","text":"Presentational mode: present food, music and hobby preferences with correct gustar agreement."},{"code":"ACTFL 4.1","text":"Compare gustar's reversed subject structure and tener idioms (tengo hambre) with English phrasing."},{"code":"ACTFL 2.2","text":"Explore foods and music of Spanish-speaking cultures as products while discussing preferences."}]},{"n":15,"title":"The Preterite: What Happened","band":"Grades 9–10","strand":"Past Tense","link":"","standards":[{"code":"ACTFL 1.3","text":"Presentational mode: recount completed past events (yesterday, last week) using the preterite at Intermediate Low."},{"code":"ACTFL 1.1","text":"Interpersonal mode: ask and answer what happened using regular and irregular preterite forms."},{"code":"ACTFL 1.2","text":"Interpretive mode: identify past-time markers and preterite forms in short texts."},{"code":"ACTFL 4.1","text":"Compare Spanish preterite endings, accents and spelling changes with the English simple past."}]},{"n":16,"title":"The Imperfect and Telling a Story","band":"Grades 9–10","strand":"Narration","link":"","standards":[{"code":"ACTFL 1.3","text":"Presentational mode: narrate childhood memories and retell a story combining preterite and imperfect at Intermediate Low."},{"code":"ACTFL 1.2","text":"Interpretive mode: follow a fable or legend such as La Llorona and distinguish background from plot events."},{"code":"ACTFL 2.2","text":"Learn legends and fables of the Spanish-speaking world as cultural products and perspectives."},{"code":"ACTFL 4.1","text":"Compare Spanish aspect (imperfect versus preterite) with English ways of expressing past time."}]},{"n":17,"title":"Pronouns, Reflexives and Commands","band":"Grades 11–12","strand":"Pronouns","link":"","standards":[{"code":"ACTFL 1.1","text":"Interpersonal mode: give and follow directions, instructions and requests with commands and pronouns at Intermediate Mid."},{"code":"ACTFL 1.3","text":"Presentational mode: present a recipe or set of directions and describe a daily routine with reflexive verbs."},{"code":"ACTFL 4.1","text":"Compare object-pronoun placement, reflexives and command forms with English structures."},{"code":"ACTFL 2.1","text":"Choose tú, usted or ustedes commands as appropriate to social practices of politeness."}]},{"n":18,"title":"The Subjunctive","band":"Grades 11–12","strand":"Mood","link":"","standards":[{"code":"ACTFL 1.1","text":"Interpersonal mode: express wishes, doubts, emotions and recommendations and respond to others' views at Intermediate Mid."},{"code":"ACTFL 1.3","text":"Presentational mode: write opinions and hypotheticals using subjunctive, conditional and si clauses."},{"code":"ACTFL 1.2","text":"Interpretive mode: recognize mood cues (dudo que, creo que, ojalá) to interpret a speaker's stance."},{"code":"ACTFL 4.1","text":"Compare the Spanish subjunctive mood with the limited traces of it in English."}]},{"n":19,"title":"The Spanish-Speaking World and Register","band":"Grades 11–12","strand":"Cultures","link":"","standards":[{"code":"ACTFL 2.1","text":"Understand register practices (tú, usted, vos) in speaking with elders, teachers and employers."},{"code":"ACTFL 2.2","text":"Learn where Spanish is spoken and how regional variation and borrowed words reflect history and perspectives."},{"code":"ACTFL 1.2","text":"Interpretive mode: read authentic texts such as signs, menus and headlines at Intermediate Mid."},{"code":"ACTFL 1.3","text":"Presentational mode: write a formal letter or email and an informal message in the appropriate register."},{"code":"ACTFL 4.2","text":"Compare formality and dialect variation across Spanish-speaking cultures and one's own."},{"code":"ACTFL 5.1","text":"Recognize Spanish in the United States and Illinois and its use beyond the classroom."}]},{"n":20,"title":"Capstone: Present and Defend","band":"Grades 11–12","strand":"Capstone","link":"","standards":[{"code":"ACTFL 1.3","text":"Presentational mode: deliver an organized, evidence-based talk on the Spanish-speaking world from notes at Intermediate Mid."},{"code":"ACTFL 1.1","text":"Interpersonal mode: answer questions and politely defend a position in a spontaneous exchange."},{"code":"ACTFL 1.2","text":"Interpretive mode: read and interpret a longer authentic passage across tenses and moods."},{"code":"ACTFL 3.2","text":"Use Spanish-language sources to gain perspectives on a topic about the Spanish-speaking world."},{"code":"ACTFL 5.2","text":"Set goals and reflect on continued use of Spanish for personal enjoyment and growth beyond the course."}]}],"codes":82},{"key":"facs","name":"Family & Consumer Sciences","subject":"K–12 · 20 units","hub":"/facs-hub","hubExists":true,"framework":{"name":"National Standards for Family and Consumer Sciences Education (NASAFACS 3.0), with Illinois Learning Standards for the K-5 units","short":"FCS / IL","note":"Codes are NASAFACS area-of-study content standards (FCS 8.2 = food safety and sanitation, etc.), plus Illinois Physical Development & Health, Mathematics and Social Science standards for the K-5 units; alignment is the course author's judgment, not a certification."},"units":[{"n":1,"title":"Kitchen Safety and Sanitation","band":"Grades 6–8","strand":"","link":"/fc1","standards":[{"code":"FCS 8.2","text":"Carry out food safety and sanitation procedures in a kitchen."},{"code":"FCS 14.4","text":"Judge the factors that affect food safety from production through consumption."},{"code":"FCS 9.2","text":"Apply risk-management steps to food safety and sanitation."},{"code":"FCS 8.3","text":"Select, use and maintain kitchen equipment according to accepted standards."}]},{"n":2,"title":"Knife Skills","band":"Grades 6–8","strand":"","link":"/fc2","standards":[{"code":"FCS 8.3","text":"Select, use and maintain kitchen tools and equipment safely and correctly."},{"code":"FCS 8.5","text":"Use professional food preparation methods and techniques to produce food products."},{"code":"FCS 8.2","text":"Follow food safety and sanitation procedures while handling tools and food."}]},{"n":3,"title":"Measuring and Reading a Recipe","band":"Grades 6–8","strand":"","link":"/fc3","standards":[{"code":"FCS 8.5","text":"Use standard food preparation techniques, including accurate measuring, to follow a recipe."},{"code":"FCS 8.4","text":"Apply menu-planning principles built on standardized recipes."},{"code":"FCS 14.3","text":"Acquire, handle and use foods to meet nutrition and wellness needs."}]},{"n":4,"title":"Hand Sewing","band":"Grades 6–8","strand":"","link":"/fc4","standards":[{"code":"FCS 16.4","text":"Show the skills needed to produce, alter or repair apparel and textile products."},{"code":"FCS 16.3","text":"Show basic textile and apparel design and construction skills."},{"code":"FCS 8.3","text":"Select, use and care for tools according to accepted standards."}]},{"n":5,"title":"The Sewing Machine","band":"Grades 6–8","strand":"","link":"/fc5","standards":[{"code":"FCS 16.4","text":"Construct, alter or repair textile products using appropriate equipment and techniques."},{"code":"FCS 16.3","text":"Apply apparel and textile design skills in a made product."},{"code":"FCS 1.2","text":"Show transferable and employability skills such as safe equipment use and following procedures."}]},{"n":6,"title":"Fabric, Fibers and Patterns","band":"Grades 6–8","strand":"","link":"/fc6","standards":[{"code":"FCS 16.2","text":"Evaluate fibers, fabrics and textile materials for their properties and uses."},{"code":"FCS 16.3","text":"Use fashion, apparel and textile design skills, including reading and using patterns."},{"code":"FCS 16.4","text":"Apply construction skills to produce a textile product from a pattern."},{"code":"FCS 2.1","text":"Manage individual and family resources such as clothing."}]},{"n":7,"title":"Cooking Methods and Heat","band":"Grades 6–8","strand":"","link":"/fc7","standards":[{"code":"FCS 8.5","text":"Use professional cooking methods and techniques across menu categories."},{"code":"FCS 8.3","text":"Use and maintain cooking equipment safely and to industry standards."},{"code":"FCS 14.3","text":"Handle and prepare foods in ways that support nutrition and wellness."},{"code":"FCS 8.2","text":"Apply food safety practices, including safe cooking temperatures."}]},{"n":8,"title":"Nutrition and Meal Planning","band":"Grades 6–8","strand":"","link":"/fc8","standards":[{"code":"FCS 14.2","text":"Evaluate the nutritional needs of individuals and families across the life span."},{"code":"FCS 14.3","text":"Plan, acquire and prepare foods that meet nutrition and wellness needs."},{"code":"FCS 14.1","text":"Analyze factors that influence nutrition and wellness practices."},{"code":"FCS 8.4","text":"Apply menu-planning principles and techniques to meet needs."},{"code":"FCS 9.3","text":"Evaluate nutrition principles, food plans and preparation techniques."}]},{"n":9,"title":"Food Science — What Happens When You Cook","band":"Grades 6–8","strand":"","link":"/fc9","standards":[{"code":"FCS 9.3","text":"Evaluate nutrition principles and food preparation techniques through the science behind them."},{"code":"FCS 14.5","text":"Evaluate how science and technology influence food, nutrition and wellness."},{"code":"FCS 8.5","text":"Apply food preparation techniques with an understanding of how ingredients react."},{"code":"FCS 9.2","text":"Apply food safety and food testing procedures."}]},{"n":10,"title":"Child Development and Care","band":"Grades 6–8","strand":"","link":"/fc10","standards":[{"code":"FCS 12.1","text":"Analyze principles of human growth and development across the life span."},{"code":"FCS 12.2","text":"Analyze conditions that influence a child's growth and development."},{"code":"FCS 4.4","text":"Provide a safe and healthy environment for children in one's care."},{"code":"FCS 15.2","text":"Evaluate caregiving practices that support children's growth and development."},{"code":"FCS 4.5","text":"Use techniques that build positive, collaborative relationships with children."}]},{"n":11,"title":"Independent Living and Money","band":"Grades 6–8","strand":"","link":"/fc11","standards":[{"code":"FCS 2.6","text":"Manage financial resources to meet personal and family goals across the life span."},{"code":"FCS 2.1","text":"Manage individual and family resources such as food, shelter, transportation and time."},{"code":"FCS 1.1","text":"Analyze strategies to manage multiple roles and responsibilities."},{"code":"FCS 2.5","text":"Analyze relationships between the economic system and consumer choices."}]},{"n":12,"title":"Capstone — Plan, Cost, Produce","band":"Grades 6–8","strand":"","link":"/fc12","standards":[{"code":"FCS 8.4","text":"Plan a menu using standardized recipes to meet a stated need."},{"code":"FCS 8.5","text":"Produce food products using professional preparation methods."},{"code":"FCS 2.1","text":"Manage resources such as money, time and materials to complete a project."},{"code":"FCS 13.5","text":"Show teamwork and leadership skills while carrying out a shared task."},{"code":"FCS 1.2","text":"Demonstrate employability skills such as planning, costing and finishing work."}]},{"n":13,"title":"Clean Hands","band":"Grades K–2","strand":"","link":"/fc13","standards":[{"code":"FCS 8.2","text":"Practice basic sanitation, beginning with proper hand washing."},{"code":"FCS 14.4","text":"Recognize how clean hands and surfaces keep food safe."},{"code":"IL 22.A.1b","text":"Identify ways to promote health and prevent illness, such as hand washing."},{"code":"IL 22.A.2b","text":"Show strategies that prevent the spread of disease, including cleanliness."}]},{"n":14,"title":"Hot, Cold and Sharp","band":"Grades K–2","strand":"","link":"/fc14","standards":[{"code":"FCS 8.2","text":"Follow basic kitchen safety rules for hot, cold and sharp things."},{"code":"FCS 8.3","text":"Use simple kitchen tools safely and put them away properly."},{"code":"IL 22.A.1c","text":"Identify dangerous situations and safe ways to respond to them."},{"code":"IL 22.A.2c","text":"Describe safety methods for handling hazards at home and in the kitchen."}]},{"n":15,"title":"Everyday Food and Sometimes Food","band":"Grades K–2","strand":"","link":"/fc15","standards":[{"code":"FCS 14.2","text":"Recognize what foods the body needs to grow and stay well."},{"code":"FCS 14.1","text":"Identify what influences the food choices people make."},{"code":"IL 23.B.1","text":"Identify healthy actions, such as a good diet, that help the body work well."},{"code":"IL 23.B.2","text":"Tell positive from negative effects of food and health choices on the body."}]},{"n":16,"title":"A Job Done to the End","band":"Grades K–2","strand":"","link":"/fc16","standards":[{"code":"FCS 13.5","text":"Show teamwork and take responsibility for a shared job."},{"code":"FCS 1.2","text":"Practice work-readiness habits such as following steps and finishing a task."},{"code":"FCS 2.1","text":"Use time and materials responsibly to get a job done."}]},{"n":17,"title":"Measure It Right","band":"Grades K–2","strand":"","link":"/fc17","standards":[{"code":"FCS 8.5","text":"Measure ingredients accurately as part of following a recipe."},{"code":"FCS 14.3","text":"Handle and prepare foods correctly using simple recipes."},{"code":"2.MD.A.1","text":"Measure length by choosing and using the right tool."},{"code":"3.MD.A.2","text":"Measure and estimate liquid volumes and masses using standard units."}]},{"n":18,"title":"The Needle and the Button","band":"Grades K–2","strand":"","link":"/fc18","standards":[{"code":"FCS 16.4","text":"Use basic hand-sewing skills to repair an item, such as sewing on a button."},{"code":"FCS 16.3","text":"Practice simple textile construction skills with a needle and thread."},{"code":"FCS 8.3","text":"Use sharp tools safely and store them correctly."}]},{"n":19,"title":"Money and Choices","band":"Grades K–2","strand":"","link":"/fc19","standards":[{"code":"FCS 2.6","text":"Make simple money decisions such as saving, spending and comparing prices."},{"code":"FCS 2.1","text":"Manage resources like money and belongings by making choices."},{"code":"IL SS.EC.1.K","text":"Explain that people make choices because they cannot have everything they want."},{"code":"IL SS.EC.1.2","text":"Show how our choices affect ourselves and others in positive and negative ways."},{"code":"2.MD.C.8","text":"Solve money problems using dollars, quarters, dimes, nickels and pennies."}]},{"n":20,"title":"Plan It, Cook It, Clean It Up","band":"Grades K–2","strand":"","link":"/fc20","standards":[{"code":"FCS 8.2","text":"Keep hands, food and work areas clean before, during and after cooking."},{"code":"FCS 8.5","text":"Prepare a simple food by following the steps of a recipe."},{"code":"FCS 14.3","text":"Plan and prepare a simple food that meets a nutrition need."},{"code":"FCS 13.5","text":"Work as a team to plan, cook and clean up."},{"code":"IL 22.A.1c","text":"Use safe practices when working around kitchen hazards."}]}],"codes":79}]};
